export default [{"id":243,"question":"رجل تُوفي وترك ولدين وبنتين وزوجة واحدة، وهناك مالٌ يُعطى لهذا الميت كل عام من قِبَل الدولة، فهل لأم الأولاد حقٌّ في هذا المال، علمًا بأنها تزوجت بعده وأنجبت؟ أفتونا مأجورين.","title":"حكم ميراث من تدفع له الدولة مالاً سنويًّا","answer":"الجواب: المال بينهم تركة، وهكذا ما تبذله الدولة بين الورثة، هذا هو القاعدة الشرعية، إلا الشيء الذي اصطلحت الدولةُ مع الموظفين على أنه يكون لبعض الورثة دون بعضٍ، على نظامٍ في موضوع التَّقاعد، هذا شيءٌ آخر، هذا حسبما وضعته الدولة؛ لأنه مساعدة منها على النظام الذي وضعته، فهذا يُعطاه مَن أقرَّت الدولةُ أنه يُعطى، ويُترك الآخرون، أما ما يكون من مساعدةٍ شهريةٍ غير التَّقاعد، أو مساعدة من الدولة له ليس على نظام التقاعد؛ فهذا كله بين الورثة: الزوجة وغير الزوجة.","link":"https://binbaz.org.sa/fatwas/4125/حكم-ميراث-من-تدفع-له-الدولة-مالا-سنويا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0283.mp3","categories":["الفرائض"]},{"id":1326,"question":"استثمار أموال الأيتام؟","title":"ما حكم استثمار أموال الأيتام وضمانها؟","answer":"الجواب:\nله أن يستثمرها ولا يعطِّلها، مأمور أن يصلحها وَلا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ [الأنعام:152]. قال العلماء: التي هي أحسن: هي التجارة فيها والتسبُّب فيها حتى تنمو.\nس: وإلا تبقى لهم يعني؟\nج: هي تبقى لهم، لكن ما ينبغي له: أن يَتَجِّر أو يعطيها من يَتَجِّر؛ لا تأكلها الصدقة، ثم يَتَجِّر بنفسه أو يعطيها لإنسان يَتَجِّر بها.\nس: والزكاة أحسن الله إليك؟\nج: تُزكّى؛ كلما دار عليها الحول تُزكّى.\nس: إذا خسر يضمنها؟\nج: إذا فرط أو تعدى، لكن إذا ما فرط أو تعدى؛ مُحْسِن ما يضمن.","link":"https://binbaz.org.sa/fatwas/21417/ما-حكم-استثمار-اموال-الايتام-وضمانها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأفضل استثمار أموال الأيتام أم عدمه.mp3","categories":["الفرائض"]},{"id":1444,"question":"هل يجوز للمُوَكَّل تأخير توزيع الميراث لمصلحةٍ؟","title":"حكم تأخير الوكيل توزيع الميراث لمصلحة","answer":"الجواب:\nنعم، ابن الزبير أجَّل؛ لأن ديون الزبير كثيرة، فخشي أن بعض الناس غائبون لم يعلموا موته، فجعل يُنادي في الموسم في الحج كل سنةٍ: مَن له على الزبير دَيْنٌ فليُوافنا، حتى مضى أربع سنين، وكان قتله سنة ست وثلاثين، معناه: أنه لم يُوزِّع إلا على رأس الأربعين، بعدما مضى أربع سنين، حتى احتاط لأبيه وبَرَأت ذمته، رضي الله عنه وأرضاه.","link":"https://binbaz.org.sa/fatwas/21540/حكم-تاخير-الوكيل-توزيع-الميراث-لمصلحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تأخير الموكل تأخير توزيع الميراث لمصلحة.mp3","categories":["الفرائض"]},{"id":1890,"question":"تُوفي رجلٌ وورثته أمُّه، وبعد ذلك ماتت وخلفها أخواها الاثنان وأولاد الولد، أيّهما يرث؟","title":"حكم ميراث رجل ورثته أمُّه ثم ماتت","answer":"الجواب:\nالميت له عيال؟\nس: نعم.\nج: وله إخوان؟\nس: لها إخوان هي، اثنان، وأولاد ولدها، أيّهما يرث؟\nج: وهي التي ماتت؟\nس: نعم.\nج: عن إخوانها؟\nس: عن إخوانها وأولاده؟\nج: يرثها أولاد ولدها، إذا كانوا ذكورًا لهم المال، وإخوانها ما يرثون، وإن كانوا بناتًا يُعْطَون الثلثين والباقي للإخوان.","link":"https://binbaz.org.sa/fatwas/22001/حكم-ميراث-رجل-ورثته-امه-ثم-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الفرائض.mp3","categories":["الفرائض"]},{"id":2041,"question":"في علم الفرائض من شروط الإرث \"عدم وجود الفرع الوارث\"، بعض المشايخ يكتفى بـقول: \"عدم الفرع الوارث\"...","title":"ما الصواب في توضيح حال الفرع الوارث؟","answer":"الجواب:\n\"عدم وجود\" أوضح، مثل الإخوة وغيرهم، الأخوات والإخوة لا يرثون مع وجود الفرع الوارث إلا عَصْبا، وكذلك الأب لا يُعطى \"عَصْب\" إلا مع عدم وجود الفرع الوارث، والأم تُعطى السدس بوجود الفرع الوارث، هذا يختلف، الأحكام تختلف.\nس: \"عدم الفرع الوارث\" لا تكفي؟\nالشيخ: الأوضح \"وجود\"، و\"عدم وجود\" من باب الإيضاح.","link":"https://binbaz.org.sa/fatwas/22158/ما-الصواب-في-توضيح-حال-الفرع-الوارث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقال عدم وجود الفرع الوارث أو يكتفى بعدم الفرع الوارث.mp3","categories":["الفرائض"]},{"id":2109,"question":"وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلَالَةً [النساء:12] ما الكلالة؟","title":"ما معنى {وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلَالَةً}؟","answer":"الجواب:\nمَن لا ولدَ له ولا والد، ليس له أبٌ، ولا أولادٌ، ولا ذرية، هذه الكلالة، فيموت عن إخوةٍ، أو أعمامٍ، أو عصبةٍ آخرين، فليس له ذرية، وليس له أبٌ ولا جدٌّ.","link":"https://binbaz.org.sa/fatwas/22227/ما-معنى-وان-كان-رجل-يورث-كلالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هي الكلالة.mp3","categories":["الفرائض"]},{"id":2205,"question":"هلك هالك عن أب وأم وإخوة لأب، كيف يكون الورث بينهم؟","title":"هل يرث الإخوة مع وجود الأب؟","answer":"الجواب:\nتُعطى الأم السدس، والباقي للأب، والإخوة ما لهم شيء؛ يحجبهم الأب.\nس: يَحجبون ويرثون؟\nج: يُحجبون ولا يرثون.","link":"https://binbaz.org.sa/fatwas/22328/هل-يرث-الاخوة-مع-وجود-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يرث الإخوة مع وجود الأب.mp3","categories":["الفرائض"]},{"id":4877,"question":"هل يحجب الأبُ الجد؟","title":"هل يُحجب الأبُ الجد؟","answer":"نعم عند جميع أهل العلم، إذا كان الأب موجودًا فالجد ما له شيء، وإن كانت الأم موجودة فالجدة ما لها شيء، عند جميع أهل العلم.","link":"https://binbaz.org.sa/fatwas/25370/هل-يحجب-الاب-الجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يحجب الأب الجد.mp3","categories":["الفرائض"]},{"id":5159,"question":"سائل يقول: إذا تُوفي زوجٌ عن زوجته قبل أن يدخل بها، هل ترثه؟ وهل تعتدّ ولها المهر؟","title":"ما عِدةُ وميراث مَنْ تُوفي زوجها قبل الدخول؟","answer":"الجواب: نعم، إذا عقد عليها ثم مات قبل الدّخول بها ترثه، وعليها العِدَّة، ولها الميراث، ولها مهرها المُسمَّى، وإن لم يكن ما سمَّى لها مهرًا يكون لها مثل مهر نسائها، كما ثبت في الحديث عن معقل بن سنان الأشجعي، وأفتى به ابنُ مسعودٍ، فإذا مات الزوج قبل أن يدخل بها، وقبل أن يُسمِّي لها مهرًا؛ فلها مهر نسائها، لا وكس، ولا شطط، وعليها العِدَّة، ولها الميراث.","link":"https://binbaz.org.sa/fatwas/30080/ما-عدة-وميراث-من-توفي-زوجها-قبل-الدخول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 104.mp3","categories":["الفرائض"]},{"id":7334,"question":"ما حكم أبناء الابن المتوفي قبل والده من ميراث الوالد، علمًا بأن الابن المتوفي له إخوة ذكور وإناث؟","title":"حكم توريث أبناء الابن المتوفى قبل والده من ميراث الوالد","answer":"الجواب:  ليس لهم إرث من جدهم، إذا مات أبوهم قبل جدهم، ليس لهم إرث، وإنما الإرث لأعمامهم، ولكن يستحب لجدهم أن يوصي لهم بشيء بالثلث، فأقل؛ جبرًا لهم، لمصابهم، لما مات أبوهم يستحب له أن يوصي لهم؛ لأنهم غير وارثين، فيستحب له أن يوصي لهم بثلثه، أو بربعه، أو بخمسه، أو بشيء معين من المال، ويستحب لأعمامهم أن يواسوهم إذا كان أبوهم ما أوصى لهم، ولكن لا يجب كما يظن بعض الناس أن هذا يجب، لا، إنما لهم وصية، يساعدون. السؤال: طيب هذا الابن الذي توفي ربما يكون هو أيضًا سبب في الثروة الموجودة القائمة الآن، كيف يحرم أبناؤه منها؟ الجواب: ولو، قال: أنت ومالك لأبيك إذا كان ما له شيء معين، ولا أعطاه أبوه شيئًا معينًا، إنما المال باسم الأب، فالمال للأب. السؤال: بعض الناس يقول: إن الجد يحق له أن يقيمهم مقام أبيهم؟ الجواب: لا بأس، إذا أوصى لهم، فلا بأس.","link":"https://binbaz.org.sa/fatwas/3408/حكم-توريث-ابناء-الابن-المتوفى-قبل-والده-من-ميراث-الوالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1721.mp3","categories":["الفرائض"]},{"id":7340,"question":"امرأة كلالة لها أخوان: أخ من أمها، وأخ من أبيها، والأخوان لهما أولاد، والأخوان توفيا قبل المرأة، من يرث أولاد الأخ من أمها، أو أولاد الأخ من أبيها من أموال هذه المرأة الكلالة، أفيدونا أفادكم الله؟","title":"حكم المرأة الكلالة إذا توفيت عن أبناء أخ","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل أنها ماتت عن أولاد أخيها من أبيها، وعن أولاد أخيها من أمها؛ فالإرث لأولاد أخيها من أبيها للذكور خاصة، العصبة يرثها أبناء أخيها الرجال دون الإناث، دون بنات الأخ، ودون أولاد الأخ لأم، أولاد الأخ لأم من الأرحام، وذوي الأرحام لا يرثون مع وجود العصبة وغيرهم من الذكور، المقصود أن إرث هذه المرأة يكون لأبناء أخيها من الأب خاصة، وهم العصبة لقول النبي ﷺ: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر وقوله ﷺ: مَا أحرز الولد أو الوالد فهو لعصبته مَن كان ... يرث العصبة لعدم وجود أهل الفروض، وهذه المرأة ليس لها أهل فروض، وإنما هم عصبة وهم أبناء أخيها فقط؛ فلهم الإرث. السؤال: الأولاد يأخذون نصيب أبيهم، أم باعتبارهم عصبة فقط؟ الجواب: باعتبارهم عصبة، بني أخ.","link":"https://binbaz.org.sa/fatwas/3428/حكم-المراة-الكلالة-اذا-توفيت-عن-ابناء-اخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1736.mp3","categories":["الفرائض"]},{"id":7346,"question":"امرأة كلالة لها أخوان: أخ من أمها، وأخ من أبيها، والأخوان لهما أولاد، والأخوان توفيا قبل المرأة، من يرث أولاد الأخ من أمها، أو أولاد الأخ من أبيها من أموال هذه المرأة الكلالة، أفيدونا أفادكم الله؟","title":"حكم المرأة الكلالة إذا توفيت عن أبناء أخ","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل أنها ماتت عن أولاد أخيها من أبيها، وعن أولاد أخيها من أمها؛ فالإرث لأولاد أخيها من أبيها للذكور خاصة، العصبة يرثها أبناء أخيها الرجال دون الإناث، دون بنات الأخ، ودون أولاد الأخ لأم، أولاد الأخ لأم من الأرحام، وذوي الأرحام لا يرثون مع وجود العصبة وغيرهم من الذكور، المقصود أن إرث هذه المرأة يكون لأبناء أخيها من الأب خاصة، وهم العصبة لقول النبي ﷺ: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر وقوله ﷺ: مَا أحرز الولد أو الوالد فهو لعصبته مَن كان ... يرث العصبة لعدم وجود أهل الفروض، وهذه المرأة ليس لها أهل فروض، وإنما هم عصبة وهم أبناء أخيها فقط؛ فلهم الإرث. السؤال: الأولاد يأخذون نصيب أبيهم، أم باعتبارهم عصبة فقط؟ الجواب: باعتبارهم عصبة، بني أخ.","link":"https://binbaz.org.sa/fatwas/3428/حكم-المراة-الكلالة-اذا-توفيت-عن-ابناء-اخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1736.mp3","categories":["الفرائض"]},{"id":7357,"question":"امرأة كلالة لها أخوان: أخ من أمها، وأخ من أبيها، والأخوان لهما أولاد، والأخوان توفيا قبل المرأة، من يرث أولاد الأخ من أمها، أو أولاد الأخ من أبيها من أموال هذه المرأة الكلالة، أفيدونا أفادكم الله؟","title":"حكم المرأة الكلالة إذا توفيت عن أبناء أخ","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل أنها ماتت عن أولاد أخيها من أبيها، وعن أولاد أخيها من أمها؛ فالإرث لأولاد أخيها من أبيها للذكور خاصة، العصبة يرثها أبناء أخيها الرجال دون الإناث، دون بنات الأخ، ودون أولاد الأخ لأم، أولاد الأخ لأم من الأرحام، وذوي الأرحام لا يرثون مع وجود العصبة وغيرهم من الذكور، المقصود أن إرث هذه المرأة يكون لأبناء أخيها من الأب خاصة، وهم العصبة لقول النبي ﷺ: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر وقوله ﷺ: مَا أحرز الولد أو الوالد فهو لعصبته مَن كان ... يرث العصبة لعدم وجود أهل الفروض، وهذه المرأة ليس لها أهل فروض، وإنما هم عصبة وهم أبناء أخيها فقط؛ فلهم الإرث. السؤال: الأولاد يأخذون نصيب أبيهم، أم باعتبارهم عصبة فقط؟ الجواب: باعتبارهم عصبة، بني أخ.","link":"https://binbaz.org.sa/fatwas/3428/حكم-المراة-الكلالة-اذا-توفيت-عن-ابناء-اخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1736.mp3","categories":["الفرائض"]},{"id":8409,"question":"إذا مات الإنسان وترك مالاً ولكنه لم يتزوج وليس له ولد ولا والدان، لكن له أخوات، كيف يمكن توزيع تركته؟","title":"كيفية تقسيم تركة من خلف أخوات فقط","answer":"الجواب: إذا مات الإنسان وليس خلفه والد، ولا ولد، ولا زوجة؛ وإنما خلف أخوات، تقسم التركة على الأخوات، يعطاها الأخوات فرضاً ورداً، إن كانت واحدة أخذت المال كله، وإن كن ثنتين قسم بينهما، وإن كن ثلاث كذلك قسم بينهن على السواء إذا كن من جهة واحدة، كأخوات أشقاء جميعاً، أو أخوات لأب جميعاً، أو أخوات لأم جميعاً، يقسم بينهم كالعصبة، فرضاً ورداً، فإذا ترك مثلاً ثلاث أخوات من أمه وأبيه جعل المال بينهن أثلاثاً فرضاً ورداً، على أصح قولي العلماء، يعطون الثلثين فرضاً والباقي رداً، وهكذا إذا كن أخوات لأب ثلاثاً أو أربعاً أو أكثر، يعطون المال فرضاً ورداً، الثلثين فرضاً، والباقي رداً كالعصبة، وهكذا لو كن أخوات من الأم ثنتين أو أكثر، يعطون الثلثين فرضاً والباقي رداً في أصح قولي العلماء.\nأما إن كن مختلفات، فإنه يوزع بينهن على حسب فروضهن، فإذا كان الموجود أختاً شقيقة وأختاً لأب، وليس هناك عصبة، ما وراءه عصبة، لا بني عم ولا غيرهم ما فيه عصبة، ما فيه إلا الأخوات أخت شقيقة وأخت لأب يجعل المال بينهم على أربعة سهام: ثلاثة للأخت الشقيقة، وسهم للأخت لأب وهو السدس فرضاً ورداً، تأخذ السدس فرضاً ورداً، والشقيقة تأخذ النصف فرضاً ورداً، أصلها من ستة تعطى النصف الشقيقة النصف ثلاثة، والأخت لأب السدس، واحد تكملة الثلثين، ويبقى اثنان يردان عليهما، يعطى الأخت لأب نصف واحد، والأخت للشقيقة واحد ونصف، فيرجع الأمر إلى أربعة، يرجع الأمر إلى أربعة من ستة، فيكون المال بينهما على أربعة سهام: للشقيقة ثلاثة سهام فرضاً ورداً، وللأخت لأب سهم واحد فرضاً ورداً، وهكذا لو كانت أخت شقيقة ومعها أخت لأم، تعطى الشقيقة ثلاثة من ستة فرضاً ورداً، والأخت لأم واحد فرضاً ورداً، ويرجع الأمر إلى أربعة مثل ما تقدم في الشقيقة والأخت لأب.\nوهكذا لو كان أخت لأب مع أخت لأم، تعطى الأخت لأب النصف، وتعطى الأخت لأم السدس واحد يبقى اثنان يردان عليهما، ترجع المسألة إلى أربعة: للأخت لأب ثلاثة فرضاً ورداً، والأخت لأم واحد فرضاً ورداً.\nأما إن كان الموجود أخوات لأم ثنتين أو أكثر وليس له عصبة بالكلية لا بني عم ولا غيرهم؛ فإن المال يعطاه الأخوات لأم فرضاً ورداً، الثلث فرضاً، والثلثان رداً عليهما ثنتين أو ثلاث أو أكثر، لهن الثلث فرضاً، والبقية رد عليهن، فإذا كن ثلاث صار بينهن أثلاثاً، وإذا كن أربع صار بينهن أرباعاً الأخوات لأم .....، أو أخوة لأم ذكور؛ لأن فرضهم الثلث إذا كن اثنين فأكثر، وما زاد هو لهم بالرد، فإذا كانوا أخوة لأم ذكور أو إناث أو ذكور وإناث فأمرهم واحد، وإرثهم سواء على السواء، لا فرق بين الذكر والأنثى، يعطون الثلث فرضاً والباقي رداً عليهم. نعم.","link":"https://binbaz.org.sa/fatwas/6293/كيفية-تقسيم-تركة-من-خلف-اخوات-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11715.mp3","categories":["الفرائض"]},{"id":8526,"question":"هذه الرسالة الثالثة في حلقة هذه الليلة وردتنا من السائل فرحان عبيد فرحان من الرياض، يقول في رسالته: توفي ابن عم جدتي وله بنتان، هل ترث منه جدتي أم لا؟","title":"حكم من مات عن بنتين وابنة عم","answer":"الجواب: ميراثه لابنتيه، للبنتين الثلثان، وأما بنت عمه فليس لها، بنت العم ليست من الورثة بل من ذوي الأرحام، فإذا مات إنسان عن بنتيه وعن بنات عمه أو بنات عمته فلبنتيه الثلثان، والباقي للعصبة.. العاصب ولو بعيداً، يعطى للعاصب كابن عمه وأخيه وابن أخيه لأبيه أو لأبيه وأمه، هؤلاء هم العصبة؛ إخوته وأعمامه من أبيه وأمه أو من أبيه فقط، كل هؤلاء عصبة، وهكذا أبناء العم وإن بعدوا هم عصبة يأخذون الباقي بعد البنتين، وأما بنت العم وبنت العمة وبنت الخال وبنت الخالة وابن الخال وابن الخالة وابن العمة هؤلاء ليسوا من الورثة، هؤلاء كلهم من ذوي الأرحام عند أهل العلم، فإن لم يوجد له عصبة ليس له إلا بنتان فقط، ما له عصبة، ليس له قبيلة ليس له عصبة، فإن المال يكون للبنتين كله، يأخذونه فرضاً ورداً، يقسم بينهما نصفين المال كله، إلا إذا كان عليه دين يبدأ بالدين، يوفى الدين، وبعد الدين المال للبنتين، أو كان أوصى بشيء بالثلث أو بالربع أو بالخمس تنفذ الوصية، تنزع الوصية أولاً ثم الباقي للورثة، وأما بنت العمة وبنت العم، بنت الخال وبنت الخالة هؤلاء لا إرث لهم، بل هم من ذوي الأرحام. نعم.","link":"https://binbaz.org.sa/fatwas/6601/حكم-من-مات-عن-بنتين-وابنة-عم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_204/20406.mp3","categories":["الفرائض"]},{"id":8527,"question":"يقول في سؤال ثان أيضاً: لقد توفيت جدتي ولها ابن أخ متوفي قبلها، فهل هي ترث منه من نصيبه يعني، علماً بأنه توفي قطيع وله أولاد عم غيرها، وجدتي هي في الدرجة الأولى؟","title":"حكم من مات عن عمة وأولاد عم","answer":"الجواب: ليس للعمة ميراث من ابن أخيها، ولا من ابن أختها، العمة لا ترث، والخالة لا ترث، وإنما ميراثه لعصبته، إذا مات وله عصبة كابن أخيه لأبيه، أو لأبيه وأمه فالعصب له، أو عمه الشقيق أو عمه لأب أو بني عمه هؤلاء هم العصبة، أما ابن أخيه لأم لا يرث، ابن أخيه لأم ليس من العصبة، وهكذا أخوه من الأم ليس بعصبة، لكن له فرض، أخوه من الأم له السدس إذا وجد، وأما ابن أخيه لأم ليس من العصبة، فالحاصل أن العمة ليست من العصبة ولا ترث من ابن أخيها، بل ميراثه للعصبة للرجال من بني عمه أو بني أخيه لأبيه وأمه أو بني أخيه لأبيه أو عمه لأبيه وأمه أو عمه لأبيه أو بني أعمامه لأبيه وأمه، أو بني أعمامه لأبيه هؤلاء هم العصبة. نعم.\nالمقدم: يعني: هذه المرأة الآن لا ترث من ابن أخيها؟\nالشيخ: أبداً ما ترث. نعم.\nالمقدم: هو ذكر بأنه قطيع يعني ماله عقب؟\nالشيخ: ولو العصبة يكفي.\nالمقدم: نعم له أولاد عم، نعم بارك الله فيكم، وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6603/حكم-من-مات-عن-عمة-واولاد-عم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_204/20407.mp3","categories":["الفرائض"]},{"id":8660,"question":"وأولى رسائل هذه الحلقة وردتنا من المستمع اليماني أحمد عبد الرحمن مسلم الشعبي يقول في رسالته: أفتونا مأجورين في رجل غادر وطنه قبل ستين سنة ولا نعرف إلى أي بلد توجه، ولا ندري هو حي أم ميت، ولكن هذا الرجل عندما غادر وطنه كان له مال وله أب وأخ من أبيه، وأخ وأخت أيضاً من أبيه فقط، نرجو منكم الإفادة لمن تكن أملاك الغائب وقد مات أبوه وأخوه الذي من أبيه وأمه أفيدونا أفادكم الله؟","title":"لمن تكون أملاك المفقود؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nهذه المسألة إحدى المسائل التي يقال فيها: إنها من مسائل المفقود، والحكم فيها يرجع إلى فضيلة قاضي البلد التي منها المفقود، فالقاضي ينظر ويحكم بما يرى بعد الدراسة والسؤال عن حال الرجل وعن أسباب فقده، ثم بعد ذلك يحكم بما يظهر له من الشرع المطهر، والمفقود له حالان:\n- حالة يكون الغالب فيها الهلاك.\n- وحالة يكون فيها الغالب السلامة، والقاضي ينظر ويعتني بالموضوع إن شاء الله ويوفق، وليس لهذا حل إلا من طريق المحكمة الشرعية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6796/لمن-تكون-املاك-المفقود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21401.mp3","categories":["الفرائض"]},{"id":9273,"question":"نعود في هذه الحلقة إلى رسالة الأخ عبدالرحمن مبروك سلامة من جمهورية مصر العربية، أخونا عرضنا بعض أسئلته في حلقة مضت وفي هذه الحلقة له مجموعة من الأسئلة يقول: هل يجوز لوالدي حرماني أنا وشقيقي من الميراث الشرعي وكتابة ميراثه لزوجته وذلكم الميراث ممثل في أرض ومنزلين؟","title":"حكم حرمان الأب لأبنائه من الميراث","answer":"الجواب: إذا كان في صحته فإنه له أن يتصرف في ماله إذا أعطى زوجته أو أعطى شخصاً آخر من أقاربه أو غيرهم أو أوقف ذلك فله الحق في ذلك مادام صحيحًا، ولكن كونه يترك له شيئاً للورثة أفضل، النبي ﷺ قال لـكعب لما أراد أن يتصدق بماله كله قال: أمسك عليك بعض مالك فهو خير لك، فالأفضل يمسك بعض ماله، لكن لو أعطاه زوجته وهو صحيح أو أعطاه بعض أقاربه، أو أنفقه في سبيل الله، أو في تعمير مسجد، أو في غير هذا من وجوه البر فلا حرج عليه لا أحد يتحجر عليه ماله يتصرف فيه التصرف الشرعي.\nلكن لا يخص به بعض الأولاد، يعطي بعض أولاده دون غيرهم لا، لابد يسوي بينهم لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم أما إذا أعطاه الزوجة أو أعطاه أمه أو أعطاه بعض إخوانه فلا حرج إذا كان رشيدًا وكان صحيحًا. نعم.","link":"https://binbaz.org.sa/fatwas/7438/حكم-حرمان-الاب-لابناىه-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15408.mp3","categories":["الفرائض"]},{"id":9278,"question":"الأخت اعتدال محمد محمد فرج بعثت برسالة تقول فيها: سبق وأن أرسلت ثلاث رسائل لقضية أرجو أن تفيدوني وأن تصل هذه الرسالة وأستمع الجواب، أنا سيدة متزوجة من إحدى وثلاثين سنة، وما زلت أعيش مع زوجي، ولي بنت وولد، البنت تزوجت والولد على وشك الزواج، وقد بنيت منزلاً مكوناً من ست شقق وأريد أن أكتب المنزل لبنتي وابني وأحرم زوجي مع أن زوجي لم يضع في بناء المنزل إلا مبالغ بسيطة جداً لا تذكر أما أولادي فلم يضعوا في بنائه أي شيء، فأريد أن أحرم زوجي من الميراث، سألت بعض الناس ليسوا علماء فمنهم من قال لي: بعد وفاتك زوجك سيتزوج ونصيبه في الميراث ستأخذه المرأة الجديدة فأولادك أولى من الغريبة، أرجو أن تفيدوني عن هذا جزاكم الله خيراً؟","title":"حكم حرمان الزوجة للزوج من الميراث","answer":"الجواب: إذا كنت في حال الصحة والسلامة فلا بأس أن تهبي هذا المبنى لابنك وابنتك وليس له الاعتراض؛ لأنك رشيدة تتصرفي في مالك، فليس له أن يعترض على تصرفك إذا كنت رشيدة لا سفيهة، وكنت صحيحة لا مريضة فأنت لك التصرف في المال بإعطائه ولدك الذكر وابنتك أو بإعطائه غيرهما أو بإيقافه وقفاً لله ، ليس عليك حرج في ذلك، والزوج إنما يحصل له الإرث بموتك أو لوجود المرض الذي ينعقد معه سبب الموت، فإذا كنت حال التصرف صحيحة سليمة رشيدة لا سفاهة فيك فالتصرف لا بأس به وليس له حق في منعك من ذلك، وإن تركت الأمر على ما هو عليه من باب المعاشرة الطيبة، ومن باب الإحسان إليه حتى يرث مع ابنك وبنتك إذا قدر الله موتك قبله فهذا حسن إن شاء الله وطيب وفيه نوع من المعاشرة بالمعروف. نعم.","link":"https://binbaz.org.sa/fatwas/7442/حكم-حرمان-الزوجة-للزوج-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15411.mp3","categories":["الفرائض"]},{"id":9750,"question":"يسأل أيضاً ويقول: كان يسأل أيضاً هل تقسم التركة قبل أن توضع الحمل؟","title":"حكم تقسيم التركة مع وجود الحمل","answer":"الجواب: هذا فيه تفصيل: تقسيم التركة قبل أن يوضع الحمل هذا فيه تفصيل: إن دعت الحاجة إلى ذلك قسم، وترك للحمل للاحتياط، إن كان الأضر على الموجودين أن يقدر الحمل ذكرين، فيقدر الحمل ذكرين أجل نصيب ذكرين، وقسمت التركة، ثم بعد ظهور الحقيقة بعد الولادة يتبين الأمر ويكمل العمل، وإن كان الأضر على الموجودين يكون الحمل بنتين أنثيين قدر الحمل أنثيين وأرصد لهما نصيبهما احتياطاً حتى لا تقع المشاكل بعد الوضع.\nوإن صبر الورثة حتى تضع وتقسم التركة على بصيرة فهذا أولى، فإن لم يصبروا؛ لأنهم في حاجة قسمت وعومل الموجودون بالأضر بالأقل، حتى لا يقع خطأ.\nمثلاً: إذا توفي إنسان عن زوجة حبلى وعن ابن، فإن الأضر على الابن أن يقدر الحمل ذكران، وقد تأتي بذكرين، فيقدر الحمل ذكران ويعطى الابن الثلث، ويبقى الثلثان موقوفان، فإن ولدت ذكراً أعطي الموجود بقية النصف وصار للمولود النصف الثاني.\nالمقدم: النصف بعد فرض الزوجة طبعاً؟\nالشيخ: إذا كان هناك زوجة تعطى فرضها، المقصود: إذا مات الميت عن ابن وعن زوجة له حبلى، تعطى الزوجة نصيبها وهو الثمن؛ لأن الموجود ابن وهو حمل تعطى الثمن ويعطى الابن ثلث الباقي احتياطاً، فمتى ولدت ذكرين أخذا الموقوف، فإن وجد ذكر صار الموقوف للولد الموجود ربعه تكميل النصف، يكون بينهما نصفين، وإن ولدت أنثى أعطي الذكر الموجود نصف الموقوف، وصار لها النصف الثاني؛ لأن لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11].\nوهكذا أشباه هذه الصورة يراعى فيها الأضر على الموجود ويحتاط فيها للحمل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7922/حكم-تقسيم-التركة-مع-وجود-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25613.mp3","categories":["الفرائض"]},{"id":9820,"question":"هذه رسالة من خلف سالمين السيد سالمين ويعمل بالعراق، يقول في رسالته: أبي كان متزوجاً بامرأة قبل والدتي وأنجب منها طفلة، ثم طلقها وتزوج بوالدتي وأنجب منها ولدين وبنتين وتوفي، وبعد وفاته بحوالي خمسة أعوام توفي أحد الأبناء، فهل لأختي الثالثة التي من أبي من المرأة السابقة حق في الميراث من أخي هذا المتوفي أخيراً أم لا؟","title":"هلك هالك عن أخت لأب وإخوة أشقاء","answer":"الجواب: لا ليس لها حق؛ لأنها أخت من الأب، وإنما الإرث لأخيه الشقيق وأختيه الشقيقتين، وأما أخته من الأب فيحجبها الأخ الشقيق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7988/هلك-هالك-عن-اخت-لاب-واخوة-اشقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26009.mp3","categories":["الفرائض"]},{"id":10213,"question":"امرأة عقد عليها رجل ولم يدخل بها، ثم مات الرجل، هل على هذه المرأة عدة؟ وهل لها ميراث؟","title":"ما العدة والإحداد والميراث لمن مات زوجها قبل الدخول؟","answer":"الجواب: نعم، إذا عقد عليها فعليها العدة إذا مات ولها الميراث، وقد ثبت ذلك عن النبي ﷺ من حديث معقل بن يسار، وقد قضى في ذلك ابن مسعود فلما بلغه أن قضيته وافقت قضاء النبي ﷺ فرح بذلك، فإذا عقد الرجل على امرأة ثم مات فإنها ترثه، وتعتد عليه أربعة أشهر وعشرًا، وتحاد عليه، وهذا بخلاف الطلاق، أما إذا طلقها قبل أن يدخل بها وقبل أن يخلو بها فإنه لا عدة عليها، كما قال الله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا [الأحزاب:49] فالمطلقة قبل الدخول والخلوة ليس عليها عدة، ولكن إذا مات عنها بعد العقد فإن عليها العدة، وهذا من المواضع التي خالف فيها الموت الطلاق، ففي هذا ترث وتعتد وتحاد، وإن كان لم يدخل بها ولم يخل بها، وأما في الطلاق فإنها لا تعتد منه ولها أن تتزوج متى شاءت من حين الطلاق. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8382/ما-العدة-والاحداد-والميراث-لمن-مات-زوجها-قبل-الدخول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33504.mp3","categories":["الفرائض","العِدَد"]},{"id":10808,"question":"رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية، باعثها المستمع يوسف عبدالغني محمود الفقيه، الأخ يوسف يقول في أحد أسئلته: والدتي توفيت قبل والدها، هل يجوز لي شرعًا أن أرث من تركته، أم لا، وإذا أخذت من تركتهـ هل هو حلال أم حرام؟","title":"حكم توريث ابن البنت من جده إذا توفيت أمه قبل جده","answer":"الجواب:  ما دامت ماتت قبل والدها ليس لك حق منه، الورث لأولاده وورثته الأحياء، من شرط إرث القريب أن يكون حيًا وقت موته قريبه، أما إذا كانت الوالدة ماتت قبل أبيها فلا حق لها في الميراث، ولا حق لك أنت إذا كان له ورثة، كبنين وبنات غير أمك، هم أحق بالميراث، وليس لك أنت حق، ولا يجوز لك أن تأخذ شيئًا من التركة، بل يجب أن ترد إن أخذت شيئًا تعطيه الورثة.  أما لو قدر أنه مات، وليس وراءه أحد إلا أنت ولد بنته، وليس له ورثة لا عصبة، ولا أهل فروض، فهذا يجوز أن ترثه على قول بعض أهل العلم، وهو الصحيح أنه يجوز أن يرثه الأرحام عند فقد الورثة من العصبة، ومن أصحاب الفروض. أما ما دام له ورثة من أولاده أو إخوته أو غيرهم من العصبة فلا حق لك أن تأخذ من التركة شيئًا؛ لأن أمك ماتت قبل أن تستحق الميراث، ماتت في حياة أبيها. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8983/حكم-توريث-ابن-البنت-من-جده-اذا-توفيت-امه-قبل-جده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35305.mp3","categories":["الفرائض"]},{"id":10898,"question":"كيف يكون الرجل أبًا غير وارث؟","title":"صور إسقاط الأب من الإرث","answer":"الجواب:  قد يكون أبًا وهو غير وارث إما لأنه رقيق مملوك فلا يرث من ابنه الحر، أو لأنه كافر وولده مسلم، أو بالعكس؛ لأنه مسلم وولده كافر فلا يرث، وقد يقتل ابنه فلا يرث منه إذا قتله، قد يقتل الوالد ولده فلا يرث منه، فإذا قام به مانع صار أبًا، وليس بوارث لكونه مخالفًا لدين الموروث، أو لكونه قاتلًا، أو لكونه رقيقًا مملوكًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9088/صور-اسقاط-الاب-من-الارث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36015.mp3","categories":["الفرائض"]},{"id":11412,"question":"تقول: أخذت امرأة من جارتها مبلغًا من المال دينًا، ولكن هذه المرأة التي لها الدين توفيت، فماذا تفعل هذه المرأة بالدين؟ هل تتصدق به عنها، أم تعطيه الورثة؟ علمًا بأن المال يسير، والورثة كثيرون، وهل إذا أعطته واحدًا من الورثة يكفي، أم لابد من علم الآخرين؟ جزاكم الله خيرًا.","title":"حكم من استدان مالاً ثم مات الدائن","answer":"الجواب:  إذا ماتت صاحبة الدين، الدين يصبح للورثة من طريق المحكمة إذا كان ما لهم وكيل من طريق المحكمة حتى تبرأ ذممهم جميعًا، إلا إذا كان لهم وكيل، أو كبير؛ تعطيه إياه، والحمد لله، كبيرهم هو الذي يتولى التركة، إذا كان التركة لها ولي يتولاها؛ تعطيه إياه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9592/حكم-من-استدان-مالا-ثم-مات-الداىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38011.mp3","categories":["الفرائض"]},{"id":11442,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (سيد جلال . م. ش. أحمد ) من القاهرة، أخونا يسأل ويقول: كم عدة المطلقة، وإذا طلقت المرأة، وبعد طلاقها بعدة شهور توفي زوجها، فهل لها نصيب في الميراث؟ علمًا بأن المرأة حامل، وزوجها قد توفي -كما ذكرت- جزاكم الله خيرًا.","title":"حكم أخذ المطلقة من الميراث","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فعدة المطلقة قد أوضحها الله في كتابه حيث قال سبحانه: وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلاثَةَ قُرُوءٍ [البقرة:228]، والصحيح أن القروء هي الحيض، هذه عدتها ثلاث حيضات بعد الطلاق، فإذا حاضت ثلاث مرات؛ بانت منه، وخرجت من عصمته، وإذا مات بعد ذلك؛ لا ترثه إذا مات بعد العدة، لا ترثه، سواءً كان الطلاق واحدة، أو طلقتين، أو ثلاثًا، متى صار الموت بعد العدة فإنها لا ترثه. أما إن كانت حاملًا كما ذكر السائل؛ فعدتها وضع الحمل، لقول الله سبحانه وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4]، فإذا مات وهي حامل؛ ففيه تفصيل: إن كان الطلاق طلقة، أو طلقتين رجعية؛ فلها الميراث. وإن كان الطلاق الطلقة الأخيرة الثالثة، أو الطلاق على عوض؛ فإنها لا ترثه، إذا كان طلقها عوضًا، دفعته إليه، وهو الخلع؛ فإنها تكون بائنة، ولا ترثه، ولو أنها حامل، أو كانت الطلقة الأخيرة الثالثة، قد طلقها طلقتين، وهذه الثالثة التي طلقها الأخيرة؛ فإنها لا ترثه أيضًا؛ لأنهما .... أجنبية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9624/حكم-اخذ-المطلقة-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38101.mp3","categories":["العِدَد","الفرائض"]},{"id":12448,"question":"يقول: بعنا قطعة أرض أربعة قيراط إلى ابن عمي، ولكنه طلب أن نكتب له عقد بيع بثمانية قيراط، والأربعة الأولى كان أبي قد باعها لعمي -رحمهما الله- ووقعنا له العقد حتى يحرم إخوته من الميراث الشرعي في الأربعة القيراط الأولى، ماذا نفعل حتى يغفر الله لنا إذ أننا حرمنا ثلاثة أشخاص من ميراثهم الشرعي؟ جزاكم الله خيرًا.","title":"الواجب على من تسبب في حرمان شخص من ميراثه","answer":"الجواب:  عليكم أن تخبروهم، فإذا سامحوك؛ فالحمد لله، وإلا عليكم أن تغرموا لهم ما ضيعتم عليهم، إن سمحوا؛ فلا بأس، وإن لم يسمحوا تعطونهم قيمة الذي فوتم عليهم، وضيعتم عليهم. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10655/الواجب-على-من-تسبب-في-حرمان-شخص-من-ميراثه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40320.mp3","categories":["الفرائض"]},{"id":12868,"question":"سؤال في الفرائض يقول فيه: توفي رجل وزوجته حامل، وقد ولدت بعد موته أنثى، وله أم وثلاثة أشقاء فكيف تقسم تركته؟","title":"حكم رجل توفي وترك زوجة وبنتًا وأمًا وإخوة أشقاء","answer":"الجواب:  تقسم تركته على النحو التالي، من أربعة وعشرين سهمًا: للزوجة الثمن ثلاثة، وللأم السدس أربعة، وللبنت النصف اثنا عشر، فهذه تسعة عشر، يبقى خمسة لأخوته الأشقاء، على سبيل التعصيب، تقسم التركة هكذا، من أربعة وعشرين سهمًا، للبنت النصف اثنا عشر، وللزوجة الثمن ثلاثة، وللأم السدس أربعة، الجميع: تسعة عشر، ويبقى خمسة من أربعة وعشرين هذا للعصبة، لقول النبي ﷺ: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر أولى يعني: أقرب رجل ذكر، نعم.","link":"https://binbaz.org.sa/fatwas/11083/حكم-رجل-توفي-وترك-زوجة-وبنتا-واما-واخوة-اشقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46518.mp3","categories":["الفرائض"]},{"id":13113,"question":"يقول هذا السائل: أفتونا في رجل تزوج بامرأة من أهل الكتاب، وأنجبت له ولدين، وعندما حضر الرجل الموت بيوم أو يومين؛ أسلمت هذه المرأة، هل ترثه، أم لا؟","title":"حكم توريث من أسلمت قبل وفاة زوجها بيوم","answer":"الجواب:  نعم ترثه، إذا أسلمت قبل الموت، ترثه، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11329/حكم-توريث-من-اسلمت-قبل-وفاة-زوجها-بيوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50819.mp3","categories":["الفرائض"]},{"id":13171,"question":"هذه السائلة تقول: عندما يكون وكيل أموال اليتامى رجل، ويعمل في مصالحهم، ويساعد العمال في المزرعة والرعاية في هذه المزرعة، ثم يأخذ من ثمر هذه المزرعة؛ علمًا بأنه لا يأخذ أجرًا على مساعدته في هذه المزرعة، والثمر كثير جدًا، يغني هؤلاء اليتامى عما أخذه الوكيل، هل يجوز ذلك؟","title":"حكم الأخذ من أموال اليتامى","answer":"الجواب:  قال الله -جل وعلا- في حق اليتامى: وَمَنْ كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَنْ كَانَ فَقِيرًا فَلْيَأْكُلْ بِالْمَعْرُوفِ [النساء:6] إذا كان غنيًا فالواجب عليه الاستعفاف، وإذا كان عليه مشقة يطلب من ولي الأمر من الحاكم أن يقدر له أجرة معلومة. وأما إن كان فقيرًا؛ فإنه يأكل بالمعروف، يأكل مع الأيتام بالمعروف، على قدر الحاجة، ولا حرج عليه من أموال اليتامى، يأكل منها، ويشرب، ويكتسي حسب الحاجة من غير إسراف، أما من أغناه الله؛ فإنه يتعفف، ولا يأكل شيئًا، فإذا أراد أجرة على عمله؛ فهذا من طريق الحاكم، من طريق المحكمة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11426/حكم-الاخذ-من-اموال-اليتامى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51107.mp3","categories":["الفرائض"]},{"id":13260,"question":"السائل يقول: رجل توفي، ولا يوجد له عصبة، وعنده مال كثير، وله خالة وعمة وبنت عم، هل يرثونه، أم لا؟","title":"توريث ذوي الأرحام","answer":"الجواب: هذا على خلاف في توريث ذوي الأرحام، بعض أهل العلم يرى توريثهم، وبعض أهل العلم لا يرى توريثهم، فإذا وقعت هذه تحال للمحكمة، تحال للمحكمة، وتنظر فيها؛ لأن هؤلاء من ذوي الأرحام. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11545/توريث-ذوي-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50905.mp3","categories":["الفرائض"]},{"id":13339,"question":"من جمهورية مصر العربية القاهرة المستمع (م. ع) بعث بقضية يقول فيها: أنا رجل عندي عشرة أولاد، كلهم أوفياء لي ولربهم، إلا واحد منهم فهو يتطاول علي بالسب والشتم، وعلى إخوانه أيضًا حتى استعمل معهم الآلات الحادة، يود أولادي أن لا يشترك معهم في أي ميراث للأسباب المذكورة، بالرغم من ثرائه الفاحش الذي يزيد عن أبيه مئات المرات، هل لي أن أمنعه نهائيًا من الميراث في الأشياء التي سيشترك فيها مع إخوانه، وأوصي له مقابل ذلك بمبالغ نقدية تعادل نصيبه تقريبًا حتى يتقوا شره، جزاكم الله خيرًا.","title":"حكم حرمان أحد الأبناء من الإرث مقابل هبة مالية","answer":"الجواب: ليس لك أن توصي له، وليس لك أن تحرمه، بل عليك أن تجتهد في إصلاحه، وهدايته، وأن تستعين بالله على ذلك، وأن تدعو له بظهر الغيب بينك وبين الله أن يهديه الله، وأن يرده للصواب، وأن تستعين بإخوانك أيضًا، وقراباتك الطيبين على دعوته إلى الله، والأخذ على يديه، حتى يستقيم على البر والصلة للرحم، وحتى يدع ما هو عليه من الباطل، فإن لم يفعل؛ فاهجره هجرًا، وأبعده عنك. وإذا مت فالله يتولى الأمر، وعلى المحاكم أن تنظر في الأمر، أما أنت لا، لا توصي له بشيء، ولا توصي بحرمانه، قد يهديه الله، قد يرجع إلى الصواب، والمحكمة تنظر في الأمر، فإن كان كافرًا إذا مت؛ لم يرث منك، وأنت مسلم، وإن كانت معصيته لم تلحقه بالكفر؛ أعطي حقه، والإثم عليه، أما أنت فلا تعمل، لا تهدي له، ولا توصي له، ولكن تنصحه، وتجتهد في طلب الهداية له من الله -عز وجل- وتستعين أيضًا بإخوانك الطيبين على نصيحته، وتوجيهه إلى الخير؛ لعل الله يهديه بأسبابك، وأنت حي. نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/11625/حكم-حرمان-احد-الابناء-من-الارث-مقابل-هبة-مالية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47614.mp3","categories":["الفرائض"]},{"id":13379,"question":"تقول: شخص ترك ثلاثة من الأولاد، ولد وبنتين، وترك الإرث للولد، وتوفي هذا الولد، وواحدة من البنات، وواحدة ما تزال على قيد الحياة، فهل يحق لها أن تطالب ابن أخيها المتوفى؟","title":"هل للأنثى أن تطالب بحقها من الميراث؟","answer":"الجواب: نعم، هذا جور جعله المال للذكر، وإلا للأنثيين، هذا جور، ولا مانع من مطالبة البنتين لأخيهم بحقهما، أو لابنه بعد موته بحقهما، ورثة الميتة، والحية تطالب بحقها، إلا أن يكون له مسوغ شرعي، يعني: يعتقد أنهما كافرتان، ليس لهما إرث منه، فهذا يرجع إلى للمحكمة، تراجع المحكمة في ذلك. أما إذا كان الولد مسلمًا، والبنتان مسلمتين، والميت مسلم، فالواجب أن تكون التركة بين الجميع بين الذكر والأنثى.. لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] تقسم بينهما، للرجل نصفها، وللبنتين نصفها، الثاني بينهما، فإذا كان في ذلك إشكال، أو نزاع؛ فهذا يرجع فيه إلى المحكمة الشرعية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11669/هل-للانثى-ان-تطالب-بحقها-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47704.mp3","categories":["الفرائض","الهبة والعطية","نصائح وتوجيهات"]},{"id":13621,"question":"السائلة التي رمزت لاسمها: بـ (ع. ش. ن) أرسلت بهذا السؤال تقول: سماحة الشيخ! توفيت والدتي، وقبل وفاتها بحوالي شهر، أو أقل قالت لي: الذهب حقي اقسميه بينك وبين أخواتك، وقد كنا ثلاث أخوات توفيت أختي الصغيرة في الحادث مع والدتي، وأختي الكبرى متزوجة، فعندما سألت إحدى الأخوات المتعلمات في الأمور الشرعية قالت: لا، بل يجب أن يقسم الذهب عليكم جميعًا، وعلى والدكم أيضًا، وجميع إخوانكم، طبعًا لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] فما رأيكم بذلك؟","title":"وجوب تقسيم التركة بين الورثة جميعًا","answer":"الجواب: نعم، هذا الواجب، جميع ذهبها، وجميع ما وراها كله للورثة جميعًا ما يخصكن، جميع ما ورائها من المال .. من ذهب .. من حلي .. من ملابس .. من عقار، كله بين الورثة جميعًا بين ذريتها، وبين زوجها إن كان لها زوج، وبين أبيها وأمها مشترك، يقول النبي ﷺ: لا وصية لوارث اللهم صل عليه وسلم. نعم.","link":"https://binbaz.org.sa/fatwas/11987/وجوب-تقسيم-التركة-بين-الورثة-جميعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53409.mp3","categories":["الفرائض"]},{"id":13628,"question":"السائلة التي رمزت لاسمها: بـ (ع. ش. ن) أرسلت بهذا السؤال تقول: سماحة الشيخ! توفيت والدتي، وقبل وفاتها بحوالي شهر، أو أقل قالت لي: الذهب حقي اقسميه بينك وبين أخواتك، وقد كنا ثلاث أخوات توفيت أختي الصغيرة في الحادث مع والدتي، وأختي الكبرى متزوجة، فعندما سألت إحدى الأخوات المتعلمات في الأمور الشرعية قالت: لا، بل يجب أن يقسم الذهب عليكم جميعًا، وعلى والدكم أيضًا، وجميع إخوانكم، طبعًا لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] فما رأيكم بذلك؟","title":"وجوب تقسيم التركة بين الورثة جميعًا","answer":"الجواب: نعم، هذا الواجب، جميع ذهبها، وجميع ما وراها كله للورثة جميعًا ما يخصكن، جميع ما ورائها من المال .. من ذهب .. من حلي .. من ملابس .. من عقار، كله بين الورثة جميعًا بين ذريتها، وبين زوجها إن كان لها زوج، وبين أبيها وأمها مشترك، يقول النبي ﷺ: لا وصية لوارث اللهم صل عليه وسلم. نعم.","link":"https://binbaz.org.sa/fatwas/11987/وجوب-تقسيم-التركة-بين-الورثة-جميعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53409.mp3","categories":["الفرائض"]},{"id":13649,"question":"السائل (م. ب. ع) في آخر أسئلته يقول: والدي لا يصلي، هل يجب علي دعوته، وأمره بإقامة الصلاة؟ ولقد أخبرني البعض من الأشخاص بأنني مسؤول عنه يوم القيامة أمام الله، وإذا مات هل يجوز لي أن أرثه، علمًا بأنه يشهد أن لا إله إلا الله؟ وجهوني بذلك سماحة الشيخ.","title":"واجب الولد تجاه والده الذي لا يصلي وهل يرثه؟","answer":"الجواب: الواجب عليك دعوته إلى الله، ونصيحته بالأسلوب الحسن، بالرفق والكلام الطيب، كما قال الله -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] وَإِنْ جَاهَدَاكَ يعني: مشركين، الوالدان المشركان. وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] فأمر بمصاحبة الوالدين الكافرين في الدنيا معروفًا، فعليك أن تصاحبه بالمعروف، بالنصيحة، بالتوجيه، بالرفق، وتستعين بالإخوان الطيبين حتى ينصحوه أيضًا من أقاربه، من إخوانه، من أعمامه؛ لعل الله يهديه بأسبابكم، والرسول يقول ﷺ: من دل على خير؛ فله مثل أجر فاعله ويقول ﷺ لعلي : لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم. فاجتهد، واصدق مع الله، واسأل ربك له الهداية في سجودك، وفي آخر الصلاة، وفي غير ذلك من الأوقات، تسأل ربك أن يهديه، وأن يشرح صدره للحق، وأن يعينه على قبول الحق، اجتهد في ذلك، واصبر وصابر، نعم. ولا ترثه إذا مات على كفره، لا ترثه، الصحيح أنك لا ترثه؛ لأن تارك الصلاة كافر، فإذا كان كافرًا؛ فإن المسلم لا يرث الكافر، يقول النبي ﷺ: لا يرث المسلم الكافر، ولا الكافر المسلم وقد اختلف العلماء فيمن ترك الصلاة تساهلًا، لا جحدًا لوجوبها، فذهب بعض أهل العلم إلى كفره كفرًا أكبر، وهذا هو الأرجح، وذهب آخرون إلى أنه لا يكفر إلا كفرًا أصغر إذا كان لا يجحد وجوبها، والأرجح أنه يكفر كفرًا أكبر، ولا ترث منه إذا كنت تصلي، وهو لا يصلي. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ عبدالعزيز.","link":"https://binbaz.org.sa/fatwas/11985/واجب-الولد-تجاه-والده-الذي-لا-يصلي-وهل-يرثه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52820.mp3","categories":["الفرائض"]},{"id":13901,"question":"في آخر أسئلة هذا السائل من اليمن يقول: سماحة الشيخ بالنسبة للملابس - ملابس والدي المتوفى - هل يجوز لي أن ألبس ملابس والدي الذي كان يلبسها وهو في حياته، علمًا بأن بعضها لم تزل جديدة؟","title":"حكم لبس الابن ملابس والده المتوفى","answer":"الجواب: لك أن تلبسها إذا كنت وحدك، أما إن كان معك شركاء فاستأذنهم إن سمحوا لك وإلا تباع مع التركة كلها، أما إذا كنت وحدك ما ورثه إلا أنت فلك أن تلبسها ولك أن تتصدق بها، ولك أن تبيعها، أما إذا كان معك ورثة فلا بد من استئذانهم إذا سمحوا لك فلا بأس وإلا تباع مع التركة. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12277/حكم-لبس-الابن-ملابس-والده-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53811.mp3","categories":["الفرائض"]},{"id":14030,"question":"المستمع من جمهورية مصر العربية محمد رشاد أحمد وهو مقيم في الرياض حاليًا بعث يسأل ويقول: كان لي عم توفي وترك قطعة أرض، وعند تقسيم الميراث لم يعطوني نصيبي؛ لأن والدي توفي قبل عمي ..الشيخ: أعد؟ يقول: كان لي عم وتوفي وترك قطعة أرض، وعند تقسيم الميراث لم يعطوني نصيبي؛ لأن والدي توفي قبل عمي، فهل لي نصيب أم لا؟ علمًا بأن عاداتنا تقضي بأنه لو مات أبي قبل جدي لا إرث، وأطلب من سماحتكم التوجيه جزاكم الله خيرًا.","title":"حكم إرث ابن الأخ","answer":"الجواب: عليك أن تراجع المحكمة أو عالمًا من علماء السنة العارفين بالمواريث حتى يعلموك ويشرحوا لك ما يجب بعد سؤالك وسؤال خصومك عن الحقيقة، الفتوى تحتاج إلى معرفة الواقع ووفاة عمك بالتفصيل ثم بعد ذلك يخبرك المفتي بما لك وما عليك.\nفالمقصود أن هذا يرجع إلى المحكمة أو إلى عالم بصير بالمواريث يعرف عن ورثة عمك ثم يبين لك مالك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12455/حكم-ارث-ابن-الاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61205.mp3","categories":["الفرائض"]},{"id":14051,"question":"لأخينا (أ. أ) من ليبيا سؤال آخر يسأل فيه عن الميراث فيقول: بالنسبة للميراث هل يجوز للورثة أن يتفقوا على عدم قسمه؟ أم لا يجوز ذلك؟","title":"حكم اتفاق الورثة على عدم قسمة التركة","answer":"الجواب: إذا كان الورثة مرشدين واتفقوا على بقاء التركة على حالها وأن يتولاها أحد منهم أو وكيل آخر يتصرف فيها وينميها كأن تكون التركة مزرعة فيقوم عليها أحدهم أو يوكلون عليها من يرعاها أو تكون التركة عمارة تؤجر ويأخذون أجرتها بواسطة وكيل أو بواسطة أحدهم، كل هذا لا بأس به إذا كانوا مرشدين، وكذلك لو كان نقود وجعلوها عند أحدهم يتصرف فيها ويتجر فيها لا بأس، المال مالهم، فإذا اتفقوا على شيء وهم مرشدون فلا بأس بذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12493/حكم-اتفاق-الورثة-على-عدم-قسمة-التركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_613/61304.mp3","categories":["الفرائض"]},{"id":14280,"question":"هذا السائل يقول سماحة الشيخ: أسأل عن أولئك الذين يقومون بتوزيع التركة أثناء الحياة؛ لأنه يرى المصلحة في ذلك للأبناء؟","title":"حكم توزيع المال بين الورثة قبل الموت","answer":"الجواب: لا حرج في ذلك إذا وزعت أمواله بين أولاده لا حرج، لكن الأفضل أنه يبقي له شيء يغنيه عنهم، يبقي له شيئًا يسد حاجته؛ لأن الأولاد قد يشحوا عليه، وقد يحصل عليه مضرة، وإن ترك التوزيع حتى يموت يكون أكمل؛ لأن الأحوال قد تختلف قد تتغير، كونه يبقي ماله في يده حتى يموت ويوصي بما أحب من الثلث أو أقل فلا بأس، هذا هو أحوط له، قد يقسم المال بين أولاده ثم يندم لعدم قيامهم بما يلزم من جهة حقه.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12739/حكم-توزيع-المال-بين-الورثة-قبل-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54917.mp3","categories":["الفرائض"]},{"id":14694,"question":"رسالة وصلت إلى البرنامج من المستمع (م. م) مصري مقيم في المملكة، عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: ما حكم من يقسم أمواله وهو على قيد الحياة، ويكتب في القسمة بيع وشراء احتيالًا على الشرع، ولكنه لا يأخذ قيمة هذه الأموال، ولكن يأخذ جزءًا من الثمار سنويًا على قدر حاجته، ما حكم هذه القسمة إذا كانت غير صحيحة؟وما حكم كاتبها وشاهدها؟وعلى من تكون الزكاة؟الشيخ: أعد أعد.المقدم: يقول: ما حكم من يقسم أمواله وهو على قيد الحياة، ويكتب في القسمة بيع وشراء احتيالًا على الشرع، ولكنه لا يأخذ قيمة هذه الأموال ولكن يأخذ جزءًا من الثمار سنويًا على قدر حاجته، ما حكم هذه القسمة إذا كانت غير صحيحة؟ وما حكم كاتبها وشاهدها؟ وعلى من تكون الزكاة؟ نرجو أن توفقوا في الإجابة، جزاكم الله خيرًا.","title":"حكم تقسيم الشخص ماله على الورثة بحيلة البيع","answer":"الجواب: هذه القسمة إن كانت على شرع الله بين أولاده وورثته على شرع الله فلا حرج فيها، ولكن ترك القسمة أولى حتى لا يحتاج إلى أحد حتى يأكل منها ويستفيد، لكن إذا قسمها بينهم ولو باسم البيع، ولم يزد أحدًا على أحد، بل أعطاهم كما شرع الله، فكونه جعلها باسم البيع هذا كذب، وعليه التوبة إلى الله من ذلك، وهو على قسمه لهم كل واحد جاه نصيبه، وله أن يأكل من ثمراتها إذا كان أبوه إذا كان هو الأب له أن يأكل، أما إذا كان ليس بالأب ولا أعطاهم إياه ما عاد له حق فيها، إذا قسمها بين إخوانه، أو بين بني عمه فملكوها إذا أعطاهم إياه وقبضوها ملكوها ما عاد له حق فيها، أما إن كانوا أولاده فله أن يأكل منها، ولو بعد القسمة؛ لأن الإنسان له أن يأكل من مال ولده أنت ومالك لأبيك. ولكن ليس له أن يقسمها على غير الشرع، يبيعها عليهم حتى يعطي هذا زيادة وهذا الولد يعطيه زيادة، وهذه البنت يعطيها زيادة ما يجوز، هذا حرام منكر، وجعله البيع حيلة.  أما إذا قسمهم لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] وجعلها باسم بيع وهو يكذب ما في بيع، فهو آثم بالكذب والقسمة في محلها، إذا كان مثلًا عنده أراضي قسمها بينهم لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] ولم يزد، ولم ينقص، ولم يحتل، ولكن جعلها باسم بيع لغرض من الأغراض، فلا يضره ذلك لا يضره، وإذا كان كاذبًا وليس هناك شيء مبيح فهو غلطان في تسمية البيع، يحتسب عليه الكذب، نسأل الله السلامة، إلا أن يكون له عذر في الكذب هذا؛ لأنه يخاف أن يصادره أحد أو كذا، إذا كان له عذر شرعي فلا حرج. المقصود: إذا كانت القسمة موافقة للشرع بين أبنائه أو زوجاته، ونحو ذلك فلا بأس، أما إذا كانت خالفة للشرع فلا يجوز، وأما بالنسبة للإخوة أو بالأقارب الآخرين كبني العم يجوز أن يفضل بعضهم على بعض وهو حي صحيح تصير عطية، إذا قسم بينهم تصير عطية لا بأس أن يعطي أخاه كذا ويعطي ابن أخيه كذا وخاله كذا لا بأس أن يعطيهم، ما هو على حسب الميراث، ما يلزمه أن يكون على حسب الميراث؛ لأن هذا خاص بالأولاد، الرسول ﷺ قال: اتقوا الله، واعدلوا بين أولادكم ما قال: اتقوا الله واعدلوا بين الورثة قال: واعدلوا بين أولادكم فلو كان له أخوان، وأعطى المال واحدًا من إخوانه في حال صحته، ولم يعط الآخر لا حرج عليه، أو أعطاهما متفاضلين لا حرج عليه، أو أعطى خاله وخلى بني عمه أعطى خاله لا بأس، ما دام في الصحة ما هو بمريض، نعم. لكن الأولى له والذي ينبغي له أن يخلي له شيئًا يعينه وينفعه، حتى لا يمن عليه الناس ويتصدقوا عليه، إما يخلي المال كله وإلا يخلي شيئًا يفيده وينفعه حتى الموت. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13190/حكم-تقسيم-الشخص-ماله-على-الورثة-بحيلة-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49001.mp3","categories":["الفرائض"]},{"id":14912,"question":"رسالة وصلت إلى البرنامج من المستمع: علي حمد يحيى الريمي، من جدة، يقول: توفي رجل وله زوجة بدون أطفال، وله أخ من أب، وله أخوات من الأب فقط، فما حصتهم، حيث قد أوصى بالثلث لبناء مسجد، فهل يحق للورثة استرداد الأرض، ودفع القيمة فقط للشخص الذي له وصية الثلث، أم لا؟ لأن الورثة قد يطلب الشفع، كما يقول في هذه الرسالة. جزاكم الله خيرًا.","title":"قسمة تركة من ترك زوجة وإخوة وأخوات ووصية بالثلث","answer":"الجواب: هذا الرجل تنفذ وصيته، وهي الثلث في تعمير مسجد كما أوصى، والثلثان تقسم بين الزوجة والإخوة، للزوجة الربع، إذا كان الميت ليس له ذرية لا ذكور ولا إناث، والباقي لأخيه وأخواته من أبيه، للذكر مثل حظ الأنثيين، كما قال الله : وَلَهُنَّ الرُّبُعُ مِمَّا تَرَكْتُمْ إِنْ لَمْ يَكُنْ لَكُمْ وَلَدٌ[النساء:12] وقال سبحانه في آخر سورة النساء: وَإِنْ كَانُوا إِخْوَةً رِجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ[النساء:176]. أما الثلث فيجب تنفيذه، وأن يصرف في تعمير مسجد، كما أوصى الموصي، وإذا كانت التركة أرضًا تباع، ويؤخذ ثلث الثمن للوصية، وإذا كان الورثة يحتاجونها؛ يشترونها بقيمتها، تباع في المزاد العلني، أو بواسطة أهل الخبرة، وإذا قدرت بواسطة أهل الخبرة، أخرج ثلث ثمنها، فإما ينادى عليها بين أهل الخبرة، وإما أن تقدر بواسطة أهل الخبرة، حتى يؤخذ الثلث من الثمن للوصية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13410/قسمة-تركة-من-ترك-زوجة-واخوة-واخوات-ووصية-بالثلث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64002.mp3","categories":["الفرائض"]},{"id":15185,"question":"المستمع: (أ. س) من الرياض، بعث بسؤال طويل بعض الشيء، يقول: رجل توفي، وله زوجة وأربعة أولاد وبنتان، وترك مبلغًا من المال على صورة دين، وبعد وفاته تم تحصيل الدين، فقامت الزوجة باستثمار ذلك المبلغ، وأضافت إليه مبلغًا مما تحصل عليه من عملها في إحدى الدوائر النسوية، وكان ذلك الاستثمار على صورة ست قطع أرض، أعطت لكل واحد منهم واحدة، فكانت أربع قطع متصلة مع بعضها، واثنتان متفرقتان. سؤالي: هل إذا بيعت القطع الأربع المتصلة مع بعضها، هل يتم تقسيم قيمتها بحيث يكون نصيب الذكر مثل حظ الأنثيين؟ وإذا كانت قيمة شراء الأرض جميعها فقط من راتب الزوجة، وليس مضافًا إليها أي مبلغًا من الإرث، فما الحكم؟","title":"قسمة تركة من مات وله زوجة وأربعة أبناء وبنتان","answer":"الجواب: الواجب على الجميع أن يميزوا بين الإرث وبين مال المرأة، إلا إذا كانت وهبته لهم، وجعلته كمال الميت، فيكون تبعًا لمال الميت.  أما إذا كانت لم تهبه لهم، فمالها لها، وما كان من راتبها لها، وأما مال الميت يوزع بينهم، للزوجتين الثمن، والباقي للأولاد أربعة أبناء وبنتين، يرجع لخمسة سهام، سهم للبنتين بينهما، وأربعة أسهم للأبناء الأربعة، للذكر مثل حظ الأنثيين. أما راتبها الذي خلطته، فهذا إن سمحت به وزع بينهم، هكذا خمسة سهام، ولها الثمن قبل ذلك ينزع، وإن لم تسمح فراتبها لها إذا بيعت الأراضي يحسب لها ما أضافت من المال تعطى إياه، والباقي بينها وبين أولادها، وإن سمحت بذلك بالمال الذي من راتبها فهو لأولادها، ولها معهم، والحمد لله. الحاصل: أن الورث في مال الميت، أما مالها فهي بالخيار، إن أعطتهم إياه قسم بينهم بالعدالة مثل الإرث؛ لأنه ليس لها أن تخص بعضهم دون بعض، يقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم إذا كانوا أولادها، فتقسمه بينهم على قسمة الله مثل مال أبيهم. أما إن كانت لا، وضعته معهم من دون قصد الهبة، لكن إما على سبيل القرض، أو على سبيل إنها تنمي الجميع فلها مالها، وللورثة مال أبيهم للذكر مثل حظ الأنثيين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13676/قسمة-تركة-من-مات-وله-زوجة-واربعة-ابناء-وبنتان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_496/49603.mp3","categories":["الفرائض"]},{"id":15399,"question":"هذان سؤالان من السائل (ع. ص. ح) من العراق، يقول في سؤاله الأول: توفي رجل وله ابنتان صغيرتان وقت وفاته، وكان يرعاهما بعده أولاد عم له، وقد ترك أرضًا، وذهب أولاد عمه إلى أحد العلماء، وخصص لهم ثلث الأرض مقابل تربيتهم للبنتين، والآن البنتان كبرتا وتزوجتا، ولهما أطفال، فهل يبقى ثلث الأرض هذا الذي تركه والدهما يبقى لأولاد عم أبيهما الذين قاموا برعايتهما؟ أم أنه حق لهما يجب أن يعاد إليهما؟ أفيدونا، جزاكم الله خير الجزاء.","title":"حكم إعطاء ثلث تركة المتوفى لمن ربى بناته","answer":"الجواب: إذا سمحتا بهذا التصرف فلا بأس، إذا سمحت البنتان بالتصرف هذا تقديرًا لتربيته وإحسانه؛ وتنفيذًا لما رآه بعض أهل العلم فلا بأس، وإن أبتا فالحكم إلى الشرع، يتحاكم معهما إلى المحكمة الشرعية في أي أرض الله، والحاكم الشرعي ينظر في الأمر، وإن سمحتا فالحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/13913/حكم-اعطاء-ثلث-تركة-المتوفى-لمن-ربى-بناته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68408.mp3","categories":["الفرائض"]},{"id":15489,"question":"سؤاله الثاني يقول: لي أخت شقيقة، وقد ماتت، ولم تترك مولودًا، ولنا إخوة من الأم، وأنا الأخ الشقيق لها، وحرموني من الميراث، وقال الإخوة من أمها: هم الذين يستحقون تركتها، وأنا أخوها الشقيق منعوني منها، فهل لي من حق معهم أم لا؟أفيدوني، أفادكم الله.","title":"ميراث الأخ الشقيق مع الإخوة لأم","answer":"الجواب: كأن السائل أخفى بعض الشيء.\nالمقدم: الله أعلم. الشيخ: كأن السائل أخفى بعض الشيء، إذا كانت الميتة ماتت عن زوج، وعن أم أو جدة وعن إخوة من أم فليس لك شيء؛ لأن التركة تكون من ستة سهام:\nللزوج النصف ثلاثة، وللأم أو الجدة السدس واحد، وللإخوة من الأم الثلث، تمت الستة، ما بقي لك شيء، والعاصب يسقط إذا ما بقي له شيء، يقول النبي ﷺ: ألحقوا الفرائض بأهلها، فما أبقت الفرائض فلأولى رجل ذكر فمعناه: أنها إذا ما أبقت شيئًا مثل هذه الصورة ما يكون له شيء. المقدم: لكن الأخ الشقيق أليس أقرب من الأخ لأم؟\nالشيخ: الأخ لأم صاحب فرض، والأخ الشقيق صاحب عصب، فإذا اجتمعت الفروض، ولم يبق شيء سقط العاصب في هذه الحالة عند جمع من أهل العلم، وهو الأرجح. وقال قوم: بالمشركة، بمعنى أنه يشرك معهم؛ لأنه شاركهم في الأم، ولكنه قول ضعيف؛ لأنه عاصب ليس بفرض، والنبي ﷺ قال: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر وهذه الفرائض لما أعطينا الزوج النصف والأم أو الجدة السدس، والإخوة لأم أعطيناهم الثلث، والله أعطاهم الثلث بنص القرآن، ما بقي للأخ الشقيق فيسقط، كما لو كان أخًا لأب، هذا هو الصواب لهذا الحديث الصحيح. أما إن كان ما وراءها إلا الإخوة لأم فقط، فلا يمكن أن تحرم، يعطى الإخوة لأم الثلث، والباقي لك، إذا كان ما وراء الأخت إلا إخوتها لأمها يعطون الثلث والباقي للشقيق، لا يمكن أن يفتي مفتٍ من أهل العلم بإسقاطك، أو كانت خلفت زوجًا وإخوة لأم، يبقى واحدًا في الستة يعطاه الأخ الشقيق، أو خلفت أمًا أو جدة وإخوة لأم، فإن الأم تعطى السدس أو الجدة، والإخوة يعطون الثلث، والباقي له، وهو النصف تعصيبًا، لكن السائل لعله أخفى الحقيقة ليشوش على المفتي الذي أفتى بإسقاطه، والمفتي الذي أفتى بإسقاطه مصيب، إذا كان الورثة زوج وأم أو جدة وإخوة لأم فإنه لا حق له؛ لعدم وجود شيء من المال بعد الفروض كما سمعت الحديث في ذلك. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14017/ميراث-الاخ-الشقيق-مع-الاخوة-لام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_690/nour_69002.mp3","categories":["الفرائض"]},{"id":15541,"question":"سؤاله الأخير يقول: ما مدى أحقية أبناء الأخت المتوفاة في تركة جدهم لأمهم؟","title":"هل يرث أبناء البنت من تركة جدهم؟","answer":"الجواب: لا يرثون، أبناء البنت ليس لهم إرث، من ذوي الأرحام، فإذا مات إنسان عن عصبة، أو عن بنين هم أعظم العصبة، أو مات عن أصحاب فروض؛ فليس لأولاد البنت شيء من الإرث، أما لو قدر أنه مات عن غير عاصب، وعن غير فرض؛ فلذوي الأرحام أحكام معروفة في توريثهم، لكن ما دام له وارث من ذوي الفرض غير الزوجين، أو من العصبة، فأولاد البنت ليس لهم شيء من جدهم أبي أمهم، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14077/هل-يرث-ابناء-البنت-من-تركة-جدهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70306.mp3","categories":["الفرائض"]},{"id":15621,"question":"هذا سؤال من المستمع رمضان محمد أبو خطوة، مصري، مقيم بالمملكة، يقول: والدتي تزوجت برجل قبل والدي، وأنجبت منه ابنتين، ثم تزوجت بأبي، وأنجبتني أنا وأختًا لي، وقد توفي والدي وترك تسعة فدادين زراعية، فورثت أنا منها ستة، وأختي ثلاثة، ثم توفيت أختي بعد أن تزوجت، ولم تخلف ذرية، فتحاكمت أنا وزوجها وإخوتها لأمها عند القاضي، حول تركتها، ولكن الذي حصل أن القاضي أعطى زوجها نصف تركتها، وأعطى إخوتها لأم النصف الثاني، وأنا أخوها الشقيق لم يعطني شيئًا منها، فما رأيكم في هذا العمل؟ وهل أستحق أنا شيئًا من تركتها أم لا؟","title":"كيفية توزيع أنصبة الميراث في مسألة المشركة","answer":"الجواب:  إن كان الواقع هو ما ذكرت.\nالمقدم: نعم؟\nالشيخ: يعني: إذا كان الواقع هو ما ذكره السائل فهذا المفتي أو هذا القاضي قد أخطأ؛ لأن للزوج النصف، ولإخوتها من الأم الثلث، فيبقى واحد من ستة لأخيها الشقيق، عصب، إلا أن تكون أمها موجودة، فإذا كانت أمها موجودة تعطى السدس، وأخواتها من الأم لهم الثلث، وزوجها له النصف، وهذه يقال لها: المشركة، ويقال لها: اليمية، ويقال لها: الحمارية، مسألة مشهورة عند العلماء، والصحيح فيها أن الشقيق يسقط هذا السائل إذا كان فيها أم مع الأخوات لأم، فإن الزوج يعطى النصف من ستة، وهو ثلاثة، وتعطى الأم السدس واحد يحجبها الإخوة عن الثلث، وتعطى الأخوات لأم الثلث، ما بقي شيء تمت الستة استغرقت الفروض المسألة، فيسقط الأخ الشقيق على الصحيح من أقوال العلماء، وهو مذهب أبي حنيفة -رحمه الله-، ومذهب الإمام أحمد -رحمه الله-، وهو المروي عن جماعة من الصحابة، مروي عن ابن عباس، وأبي موسى الأشعري، وأبي بن كعب، وجماعة من الصحابة وأهل العلم، وهو الصواب؛ لقول النبي ﷺ: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر. ولعل هذا هو الواقع؛ لأن السائل ما ذكر الأم، ولا ذكر أنها ماتت الأم، فإذا كان الأم موجودة، فالذي فعله القاضي هو الصواب، وهو الحق، خلافًا لمذهب الشافعي ومالك، فالزوج له النصف من ستة: ثلاثة، والأم لها السدس: واحد، وأخوات الميتة من أمها لهم الثلث، هذه ستة، ما بقي شيء، فالشقيق يسقط ولو كان عاصبًا قويًا، لكن استغرقت الفروض ما بقي له شيء، والرسول ﷺ قال: اقسموا الميراث بين أهل الفرائض على كتاب الله، فما أبقت الفرائض فهو لأولى رجل ذكر وفي لفظ: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر وأولى رجل هو الشقيق، ولم يبق له شيء فيسقط. فالمقصود: أن حكم القاضي صحيح إن كانت الأم موجودة، أما إن كانت الأم مفقودة فهو مخطئ. المقدم: القاضي لم يحسب شيئًا للأم. الشيخ: فالقاضي إذا أراد أن يعطي الزوج النصف، ويعطي الإخوة لأم الثلث يبقى واحد للشقيق، إذا كان ما لها أم، لكن أخشى أن السائل نسي الأم، أخشى أن السائل نسي الأم، فظلم القاضي، نعم.\nالمقدم: أقصد لو كانت الأم موجودة لها السدس؟\nالشيخ: لها السدس.\nالمقدم: والباقي للإخوة لأم؟ الشيخ: ثلث، لهم ثلث، فرض ولا بقي شيء، انتهى. المقدم: ولم يبق شيء. الشيخ: نعم، فيسقط الأخ الشقيق على الصحيح من أقوال العلماء. المقدم: إنما لو اتضح أنه فعلًا الأم غير موجودة؟\nالشيخ: فله السدس عصبًا. المقدم: الذي هو الباقي تعصيبًا؟\nالشيخ: تعصيبًا، ما هو بفرض، تعصيب، يعني: واحد من ستة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14164/كيفية-توزيع-انصبة-الميراث-في-مسالة-المشركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_696/nour_69603.mp3","categories":["الفرائض"]},{"id":15798,"question":"يقول: عندي قطعة أرض ميراث من أبي المتوفى، وهذا الميراث لم يوزع حتى الآن، وقد تركتها لإخوتي يزرعونها، ويحصدون ما يأتي منها، وقد يسر الله لي رزقًا غيرها، فهل أكون بهذا مقصرًا في حق أولادي لأحقيتهم في هذه الأرض؟جزاكم الله خيرًا.","title":"حكم ترك الشخص نصيبه من التركة لأخوته","answer":"الجواب: لا حرج عليك، ولست مقصرًا بل محسنًا، وأولادك لهم الله، أنت حي، وتقوم عليهم الآن، ولا حق لهم فيه ذلك الحق لك، فإذا سمحت بهذا لإخوتك مراعاة لحاجتهم، أو لصلة الرحم، فأنت مأجور، ولا شيء عليك، ولا حق لأولادك في هذا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.\nيقول: إذا أردت بناء بيت في نصيبي هذا، وأخذته من إخوتي، فهل أكون معتديًا عليهم؟ الشيخ: إذا تصالحت أنت وإياهم، إذا تصالحت أنت وإخوتك في أرض البيت فلا حرج، وإلا فليس لك إلا نصيبك من الإرث، تقتسمون بواسطة أهل الخبرة، حتى يعطى كل واحد حقه، أما إذا تراضيتم وأعطوك شيئًا من الأرض وتسامحتم فيما بينكم حتى تقيم عليها بيتًا وهم موسرون فلا حرج عليك في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14388/حكم-ترك-الشخص-نصيبه-من-التركة-لاخوته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74304.mp3","categories":["الفرائض"]},{"id":15799,"question":"يقول: عندي قطعة أرض ميراث من أبي المتوفى، وهذا الميراث لم يوزع حتى الآن، وقد تركتها لإخوتي يزرعونها، ويحصدون ما يأتي منها، وقد يسر الله لي رزقًا غيرها، فهل أكون بهذا مقصرًا في حق أولادي لأحقيتهم في هذه الأرض؟جزاكم الله خيرًا.","title":"حكم ترك الشخص نصيبه من التركة لأخوته","answer":"الجواب: لا حرج عليك، ولست مقصرًا بل محسنًا، وأولادك لهم الله، أنت حي، وتقوم عليهم الآن، ولا حق لهم فيه ذلك الحق لك، فإذا سمحت بهذا لإخوتك مراعاة لحاجتهم، أو لصلة الرحم، فأنت مأجور، ولا شيء عليك، ولا حق لأولادك في هذا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.\nيقول: إذا أردت بناء بيت في نصيبي هذا، وأخذته من إخوتي، فهل أكون معتديًا عليهم؟ الشيخ: إذا تصالحت أنت وإياهم، إذا تصالحت أنت وإخوتك في أرض البيت فلا حرج، وإلا فليس لك إلا نصيبك من الإرث، تقتسمون بواسطة أهل الخبرة، حتى يعطى كل واحد حقه، أما إذا تراضيتم وأعطوك شيئًا من الأرض وتسامحتم فيما بينكم حتى تقيم عليها بيتًا وهم موسرون فلا حرج عليك في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14388/حكم-ترك-الشخص-نصيبه-من-التركة-لاخوته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74304.mp3","categories":["الفرائض"]},{"id":15801,"question":"من السيد العداني الحسن، تاجر بسوق الخميس، في المملكة المغربية، رسالة يقول فيها: إنني من المتابعين لبرنامجكم القيم الذي أنصت له باستمرار، وأشكركم على هذه البادرة الطيبة غاية الشكر، وأود أن أوجه سؤالي التالي:توفي رجل وترك زوجة وبنتين وأخاً من الأم فقط، فهل يرث أخوه هذا أم لا؟ وإذا كان يرث فعلًا فما هو نصيب كل واحد من الورثة؟ علمًا أن التركة التي خلفها هي من ماله الخاص، في انتظار إجابتكم، جزاكم الله خيرًا.","title":"قسمة تركة من خلف زوجة وبنتين وأخ لأم","answer":"الجواب: هذا الميت تقسم تركته من أربعة وعشرين سهمًا، للبنتين الثلثان ستة عشر، وللزوجة الثمن ثلاثة، ويبقى خمسة يعطاها العاصب إن كان العاصب ابن عم، ولو بعيدًا، يعطاها العاصب، فإن لم يكن له عاصب، فإنها ترد على البنتين عند أهل العلم.  أما الأخ لأم فلا يرث مع وجود الفرع الوارث؛ لأن الله -جل وعلا- قال في كتابه العظيم: وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلالَةً أَوِ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ[النساء:12] والكلالة من لا ولد له ولا والد ذكر، وهذا له ولد وهو البنتين.  فالمقصود: أن شرط الأخ لأم أن تكون الإرث كلالة لهذه الآية الكريمة، وهي قوله سبحانه في سورة النساء: وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلالَةً أَوِ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ[النساء:12] يعني: لأم فَلِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ[النساء:12].  وهذا ميت له بنات فلم تقم مسألة الكلالة، فيكون الأخ لأم لا حق له في الإرث والباقي بعد الزوجة والبنتين يكون لأقرب العصبة، فإن لم يكن له عصبة فإنه يعطى الباقي للبنتين ويكون إرثهن فرضًا وردًا؛ ستة عشر فرضًا وخمسة ردًا، هذا هو الصواب والمفتى به، وهو قول أهل العلم في هذه المسألة للآية الكريمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14395/قسمة-تركة-من-خلف-زوجة-وبنتين-واخ-لام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74310.mp3","categories":["الفرائض"]},{"id":15999,"question":"من يعلم أن مورثه اغتصب مالًا أو أرضًا أو سرق، هل يحق لذلكم الوارث أن يرثها أو يعيدها أو يتصدق بها؟","title":"كيفية التصرف في الإرث إذا كان مغصوبًا أو مسروقًا","answer":"الجواب: الواجب على الوارث أن يعيدها لصاحبها إذا عرفه، أما إذا كان لا يعرفه فيصدق بها عنه، هي في ذمة الميت وذمته هو، وليس له أن ينتفع بها ما دام يعلم أنها مغصوبة أو سرقة، فالواجب ردها إلى صاحبها إن عرف وإلا فالصدقة بها في وجوه الخير بالنية عن صاحبها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14620/كيفية-التصرف-في-الارث-اذا-كان-مغصوبا-او-مسروقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74708.mp3","categories":["الفرائض"]},{"id":16010,"question":"أيضًا يقول سماحة الشيخ حول الموضوع تقريبًا: والدي صرف مبلغ أربعة آلاف جنيه في زواجي ولي أخت تم زواجها وصرف عليها في الزواج مبلغ عشرة آلاف جنيه مصري، فهل يحق لها المطالبة في الميراث بعد وفاة الوالد؟","title":"حكم حرمان البنت من الميراث لكثرة مصاريف زواجها","answer":"الجواب: أعطوها ميراثها ولا تقطعوها ميراثها؛ لأن العطية السابقة شيء آخر غير الميراث، وإذا أردتم مطالبتها بشيء مما أعطاها؛ لأنه زادها عليكم هذا شيء يحكم بينكم فيه الحاكم الشرعي تحكمون أحد العلماء المعروفين بالعلم والفضل وينظر في ذلك، وإن سمحتم عنها وأعطيتموها الميراث فهو خير لكم وأحسن في العاقبة -إن شاء الله-، ومن عفا وأصلح فأجره على الله هذه رحم صلتها مطلوبة وأنتم على خير.\nيقول النبي ﷺ في الحديث الصحيح: من أحب أن يبسط له في رزقه وأن ينسأ له في أجله فليصل رحمه، وهي رحم لكم فإذا سمحتم عنها فذلك خير، وإن حاكمتموها عند عالم من علماء الشرع المعروفين بالخير والعلم والفضل يحكم بينكم فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14645/حكم-حرمان-البنت-من-الميراث-لكثرة-مصاريف-زواجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74718.mp3","categories":["الفرائض"]},{"id":16375,"question":"من المستمع عبدالحميد أحمد رسالة وضمنها سؤالين، في سؤاله الأول يقول: قبل سفري أعطتني والدتي مبلغ خمسمائة جنيه على سبيل السلف، وبعد سفري بمدة، وخلال وجودي خارج بلدي علمت أن الله قد اختارها إلى جواره، فما حكم الشرع في هذا المبلغ، علمًا أن لي أختًا زوجها متوفى، وتعول أبناء كثيرين، فهل أعطيها المبلغ، أم ما هو الحكم؟ جزاكم الله خيرًا.","title":"كيفية التصرف في أموال الميت التي أقرضها للورثة","answer":"الجواب:  بينك وبين أختك على قسمة الله -جل وعلا- إذا كانت الوالدة ليس خلفها من الورثة سواك، وأختك فإن هذا المبلغ بينكما لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] إلا أن تسمح لك بحقها، وهي مرشدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15073/كيفية-التصرف-في-اموال-الميت-التي-اقرضها-للورثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75405.mp3","categories":["الفرائض"]},{"id":16551,"question":"يسأل سؤالًا آخر فيقول: توفي رجل، وترك ثلاثة أولاد ذكورًا، وزوجة، وإخوة أشقاء أربعة، وأم للمتوفى، وليست هناك وصية، أو دين، كيف يوزع الميراث في وجود أم المتوفى؟ وكيف نوزعه في عدم وجودها أي: بعد وفاتها؟ جزاكم الله خيرًا.الشيخ: أعد.المقدم: يقول: توفي رجل، وترك ثلاثة أولاد ذكورًا، وزوجة، وإخوة أشقاء أربعة، وأمًا للمتوفى، وليست هناك وصية، أو دين، كيف يوزع الميراث في وجود الأم؟ وكيف يوزع في عدم وجودها؟","title":"تقسيم تركة بين أبناء ذكور وزوجة وأم وإخوة أشقاء","answer":"الجواب: مع وجود الأم تقسم التركة من أربعة وعشرين سهمًا متساوية، وتعطى الزوجة الثمن؛ ثلاثة، والأم السدس؛ أربعة، والباقي للأولاد إذا كانوا ذكورًا، أو ذكورًا وإناثًا، للذكر مثل حظ الأنثيين، والإخوة ليس لهم شيء؛ يحجبهم الأولاد الذكور، فإن كان الأولاد بناتًا؛ لأنه: يقال للبنت: ولد، ويقال للذكر: ولد.   كما قال تعالى: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] سمى الابن ولدًا، وسمى البنت ولدًا، أما إن كان الأولاد الموجودون إناثًا؛ فإن لهن الثلثين؛ ستة عشر، والأم لها السدس؛ أربعة، والزوجة لها الثمن؛ ثلاثة، فتعود إلى سبعة وعشرين، والإخوة ليس لهم شيء على الحالين، إن كانوا ذكورًا؛ فالذكور يحجبونهم، وإن كانوا إناثًا؛ استغرقت الفروض التركة، ما بقي لهم شيء. فعلى كل حال الإخوة ليس لهم شيء، وإن كان الأولاد ذكورًا وإناثًا مثل: بنتان وولد، أو ولدان وبنت، فالأم لها السدس؛ أربعة، والزوجة لها الثمن؛ ثلاثة من أربعة وعشرين، يبقى سبعة عشر للأولاد: للذكر مثل حظ الأنثيين، بينهم، لقوله تعالى: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] والإخوة ليس لهم شيء بكل حال، في جميع الصور. أما لو كانت الأم معدومة، بأن كانت ماتت قبل ولدها، وليس وراءه إلا الزوجة والأولاد؛ فإنها تقسم من ثمانية، ثمانية سهام متساوية. للزوجة ثمن واحد، الزوجة لها الثمن، سهم من ثمانية، والباقي سبعة، للأولاد إذا كانوا ذكورًا، أو ذكورًا وإناثًا، السبعة لهم، أما إن كان الأولاد إناثًا محضًا ثلاث بنات؛ فإن المسألة تقسم من أربعة وعشرين، إن كان ما هنا أم، للزوجة الثمن ثلاثة، والبنات لهن الثلثان ستة عشر، يبقى خمسة للإخوة عصبًا لهم لقول النبي ﷺ: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر والأولى هنا هم الإخوة، هم أقرب؛ فيعطون الخمسة الباقية من الأربعة والعشرين، تعطى الزوجة الثمن ثلاثة، والبنات الثلثان ستة عشر، يبقى خمسة للإخوة بينهم، كانوا ذكورًا بينهم على السواء، وإن كانوا ذكورًا وإناثًا للذكر مثل حظ الأنثيين، لقوله تعالى في آخر سورة النساء: وَإِنْ كَانُوا إِخْوَةً رِجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:176] سواء إخوة لأب، أو إخوة أشقاء، يعني: كلهم إما إخوة لأب كلهم، أو إخوة أشقاء كلهم للذكر مثل حظ الأنثيين. فإن كان بعضهم أشقاء، وبعضهم لأب؛ فالعصب للأشقاء، والإخوة لأب محجوبون بهم، ساقطون، فلو كانوا مثلًا خمسة إخوة واحد شقيق، والبقية لأب، فالباقي يأخذه الشقيق، والإخوة لأب يسقطون؛ لأنه أقوى منهم، أكثر قرابة، هذا تفصيلها، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15287/تقسيم-تركة-بين-ابناء-ذكور-وزوجة-وام-واخوة-اشقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75713.mp3","categories":["الفرائض"]},{"id":16721,"question":"أخيرًا يسأل أخونا سؤالًا كبيرًا جدًا، فيقول: كيف تقسم تركة الميت؟","title":"كيفية تقسيم تركة الميت","answer":"الجواب: تقسم التركة على كتاب الله، وعلى سنة رسوله ﷺ، وقد وضح القرآن والسنة حكم المواريث بأبين بيان، وأوضح بيان، تقسم التركة عند أهل العلم، صاحب الحاجة يقدم السؤال لأهل العلم المحكمة، أو غيره من أهل العلم، ويقسموا التركة، والتركة والمواريث تختلف، ليست على حد سواء، فإذا نزلت نازلة بأحد؛ فإنه يقدم الورثة إلى المحكمة، أو إلى العالم المعروف؛ وهو يقسم بينهم التركة.  مثلاً يقول: مات ميت عن زوج وابن، ماتت امرأة عن زوجها وابنها، يقول لهم العالم: التركة تقسم بينهم أرباعًا للزوج الربع، والباقي للابن؛ لأن الله يقول سبحانه: وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَاجُكُمْ إِنْ لَمْ يَكُنْ لَهُنَّ وَلَدٌ فَإِنْ كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ الرُّبُعُ[النساء:12] يعني: الزوج، لو مات ميت عن زوج، ماتت امرأة عن زوجها وأخيها، أخيها الشقيق، أو أخيها من الأب، العالم يقول: المال بينهما للزوج النصف -كما قسم الله- والباقي للأخ عصب، أو ماتت امرأة عن زوجها وأبيها؛ المال بينهما نصفين، للزوج النصف فرضًا، والباقي لأبيها على سبيل التعصيب، أو مات رجل عن زوجة، وعن أبيه؛ تقسم التركة بينهما للزوجة الربع، والباقي للأب، أو مات رجل عن ابن وبنتين؛ التركة تقسم للأربعة: للابن اثنان، ولكل بنت واحد؛ لأن الله يقول سبحانه: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ[النساء:11]. وهكذا لو مات إنسان عن أمه، وعن ابنه؛ تقسم التركة من ستة، للأم السدس واحد، والباقي للابن؛ لأن الله -جل وعلا- يقول: وَلِأَبَوَيْهِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ مِمَّا تَرَكَ إِنْ كَانَ لَهُ وَلَدٌ [النساء:11] والولد يشمل الذكر والأنثى. المقدم: لو تكرمتم سماحة الشيخ نعيد الآية ..؟ الشيخ: وَلِأَبَوَيْهِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ مِمَّا تَرَكَ إِنْ كَانَ لَهُ وَلَدٌ [النساء:11] يعني الأبوان الأم والأب، فإذا مات إنسان عن أمه، أو عن أبيه، أو عنهما، وله ولد له ابن، أو بنت؛ يكون للأم السدس، والأب السدس، وللبنت النصف، وإن بقي شيء فيأخذه الأب زيادة تعصيب، أما إن كان الموجود ابنًا ما هو ببنت ابن، فالأم لها السدس، والأب له السدس، والباقي للابن من ستة أسهم، للأب السدس، والأم السدس، والباقي للابن، أو ابن الابن، نعم.","link":"https://binbaz.org.sa/fatwas/15465/كيفية-تقسيم-تركة-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76107.mp3","categories":["الفرائض"]},{"id":16915,"question":"رسالة وصلت إلى البرنامج من المستمع سامح طارق، من العراق، سامح يسأل جمعًا من الأسئلة، يقول في أحدها: توفي عمي قبل جدي بزمن، وترك بنتًا واحدة، وبعد موت جدي بفترة طويلة؛ حصلت قسمة الأرض التي يمتلكها جدي بين عمومتي، فهل هذه البنت تشارك حصة عمي المتوفى قبل جدي؟ وإذا كانت الإجابة بلا، فبكم؟","title":"حكم إرث البنت مع أعمامها من جدها","answer":"الجواب: ليس لها حق في الإرث، إن كان أبوها مات قبل أبيه، فالحق للموجودين، الأبناء الموجودين، والميت لا حق له، الذي مات قبل أبيه، وإنما الحق للورثة الموجودين، البنين والبنات، للذكر مثل حظ الأنثيين، كما قال تعالى: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]. إلا إذا كان جدها أوصى لها بشيء، إذا كان أوصى لها بشيء من الدراهم، أو جزء مشاع كالربع، أو الخمس؛ لا بأس، لكن ليس له أن يوصي بأكثر من الثلث، إذا أوصى لها بالثلث، أو أقل، أو بدراهم معينة، لا تزيد على الثلث، أو بأرض، أو بيت لا يزيد على الثلث، لا بأس، أما إن زاد على الثلث، فلا يسمح لها بالزيادة إلا برضا الورثة، إذا أوصى لها بشيء يزيد على الثلث؛ فالزائد ليس لها حق فيه، إلا برضاهم، يعني: الورثة إذا كانوا مرشدين، أما إن كانوا قاصرين؛ لا، لا تعطى الزيادة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15689/حكم-ارث-البنت-مع-اعمامها-من-جدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82608.mp3","categories":["الفرائض"]},{"id":16917,"question":"يقول: إذا كان أصل ملكية الأرض للدولة، وهي مستغلة من قبل الأشخاص منذ زمنٍ طويلٍ جدًا، فهل يجوز معاملة الذكر معاملة الأنثى عند القسمة، على ورثة أحد الأشخاص؟","title":"حكم قسمة العقار الذي أصل ملكيته للدولة","answer":"الجواب: إذا كانت الدولة قد أعطتهم، أقطعتهم هذا، أو اشتروا منها، لا بأس، وإلا مادام على ملك الدولة، فهم إما مستأجرون، وإما معارون، فليس لهم حق في الأرض، إلا إذا كانت الدولة قد أقطعتهم إياها، منحتهم إياها، فذلك على حسب الإقطاع، كل له نصيبه، أو الدولة باعت عليهم، أما إذا كان لا بيع، ولا إقطاع، وهي على حساب الدولة؛ فهم يعتبرون: إما مستأجرون، يعتبروا إما مستأجرون، وإما معارون، وإما مغتصبون، إذا كانوا دخلوها بالقوة، بغير إذن، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15692/حكم-قسمة-العقار-الذي-اصل-ملكيته-للدولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82609.mp3","categories":["الفرائض"]},{"id":17223,"question":"من الأخ: خضري محمد رضوان، مصري مقيم في حائل، يسأل سماحتكم يقول: هل الإخوة يتوارثون فيما بينهم، ولا سيما إذا كانوا من أمهات مختلفات؟","title":"الحالات التي يرث فيها الإخوة بعضهم بعضًا","answer":"الجواب: نعم، الإخوان يتوارثون، سواء كانوا أشقاء، أو لأب، أو لأم يتوارثون، إذا لم يوجد حاجب يحجبهم، أما إذا كان الأب موجودًا يحجبهم، أو الابن ابن الميت، أو ابن الميت يحجبهم، يحجب الإخوة، وهكذا الجد على الصحيح، أبو الأب يحجب الإخوة، إذا مات ميت عن أبيه، وإخوته فالمال لأبيه، أو مات عن ابنه وإخوته فالمال لابنه، أو عن ابن ابنه فالمال لابن ابنه، والإخوة ليس لهم شيء، فالإخوة محجوبون بالأب، والابن وابن الابن وإن نزل، سواء كان مع الابن وابن الابن بنات، أو ما معهم بنات، فالابن الذكر، أو مع بنات يحجبون الإخوة، وهكذا ابن الابن وحده، أو مع أخواته يحجبون الإخوة، وهكذا الجد على الصحيح يحجب الإخوة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16049/الحالات-التي-يرث-فيها-الاخوة-بعضهم-بعضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72319.mp3","categories":["الفرائض"]},{"id":17262,"question":"السائل يقول في هذا  يا سماحة الشيخ، والدي كتب الميراث لنا نحن البنين دون البنات، وترك زوجته وأخواتي البنات؛ بحجة أن الميراث بسيط، وأن أخواتي البنات تعلمن، وعملن، وجهز لهن بيت الزوجية، وهذا يعادل ميراثهن، ما نصيحتكم للآباء حول هذا الموضوع يا سماحة الشيخ؟","title":"حكم تخصيص الأبناء بالميراث دون البنات","answer":"الجواب: لا يجوز للآباء أن يخصوا الأبناء بشيء، بل الواجب أن يدعوا التركة للجميع: لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] أما ما أعطاهن وقت الزواج هذا شيء آخر ما له تعلق بالورث، أما الورث يجب أن يكون بين الجميع على قسمة الله، ولا يجوز للأب أن يخص الذكور بشيء، ولا أن يخص البنات بشيء، بل يتركهم على قسمة الله: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] ولا يجوز أن يخص أحدًا منهم بشيء، لا كبيرًا، ولا صغيرًا، ولا عالمًا ولا جاهلًا، ولا ذكرًا ولا أنثى، بل يجب أن يترك الأمر على قسمة الله بين الجميع. نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16101/حكم-تخصيص-الابناء-بالميراث-دون-البنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59213.mp3","categories":["الفرائض","الهبة والعطية"]},{"id":17332,"question":"امرأة ماتت، ولها ورث من والدها، ولها ولدين، وإخوان، وبنتين، وأمها، ما نصيب الأم من ميراث ابنتها يا شيخ؟","title":"تقسيم تركة امرأة ماتت عن أولاد وإخوة وأم","answer":"الجواب: الأم لها السدس مع الولد، يقول : وَلِأَبَوَيْهِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ مِمَّا تَرَكَ إِنْ كَانَ لَهُ وَلَدٌ [النساء:11] فهذه المرأة إذا ماتت عن أولاد، وعن إخوة، وعن أم، الأم لها السدس، وإن كان لها زوج يعطى الربع، والباقي لأولادها ذكورهم، وإناثهم لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] لقول الله سبحانه: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] والإخوة ما لهم شيء مع الأولاد، يمنعهم الأولاد، إذا كان لها أولاد ذكور؛ فالإخوة ليس لهم شيء كلهم، ولو ابنًا واحدًا يمنعهم الولد. فإذا ماتت عن أمها، وابنها، وبنتيها؛ صار للأم السدس المسألة من ستة: للأم السدس واحد من ستة، والباقي بين الابن والبنتين، أنصافًا للابن النصف والبنتين النصف لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]. وإذا ماتت عن ابن، وثلاث بنات، وأم، أو أب، فالمسألة من ستة، للأم السدس، أو الأب إن كان أبًا له السدس، أو جد له السدس، أو جدة لها السدس، والباقي خمسة للابن، والثلاث البنات؛ اثنان للابن، وثلاثة للبنات، كل واحدة لها واحد. وإذا ماتت عن أبوين - أم وأب - وعن ابن، وبنتين صارت من ستة أيضًا، للأب السدس، والأم السدس، والباقي أربعة للابن، والبنتين، للابن اثنان، والبنتين اثنان، لكل واحد منهما واحد، وإن كان لها زوج يعطى الربع لقوله سبحانه: وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَاجُكُمْ إِنْ لَمْ يَكُنْ لَهُنَّ وَلَدٌ فَإِنْ كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ الرُّبُعُ [النساء:12]. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16163/تقسيم-تركة-امراة-ماتت-عن-اولاد-واخوة-وام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76906.mp3","categories":["الفرائض"]},{"id":17410,"question":"هذه مستمعة من الأردن كتبت -الحقيقة- سؤالًا طويلًا، ملخصه: سماحة الشيخ -وقد كتبت هذه الرسالة بأسلوبها الخاص- تقول: لقد جرت العادة في قريتنا بأن البنات لا يرثوا، وإنما يعطون من بعض المال مقابل أن تتنازل هذه البنات لإخوتها عن حصتها في الميراث، ويقولون: بأنه بيع وشراء، وأنا أحرص على إرضاء والدي، وقد عرض علينا والدي -نحن البنات- مبلغًا من المال مقابل التنازل لإخواني عن نصيبنا نحن البنات، تقول: علمًا بأن المال من والدي، وليس من إخوتي، وقد قلت لوالدي: بأن هذا لا يجوز، وبأن ذلك يعرضه للعذاب، ولكن إخوتي يقولون لأبي: بأنهم لن يعملوا بالأرض، ولا بالشجر إلا إذا سجل بأسمائهم، وأبي مصر على الموافقة، فنرجو من سماحة الشيخ الإجابة.","title":"حكم حرمان البنات من الإرث","answer":"الجواب: لا يجوز للأب أن يخص البنين بالورث، ولا أن يلزم البنات بأن يأخذن عوضًا، هذا منكر، هذا من عمل الجاهلية، ولا يجوز، بل يجب أن يساعد على الأمر الشرعي، وأن تكون التركة للجميع، للبنين والبنات للذكر مثل حظ الأنثيين كما قال الله سبحانه: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:12]. وهكذا الإخوة الأشقاء، والإخوة لأب يرثون للذكر مثل حظ الأنثيين كما قال -جل وعلا-: وَإِنْ كَانُوا إِخْوَةً رِجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:176] يعني: الإخوة الأشقاء، والإخوة لأب، هذا واجب، ولا يجوز للأب، ولا الأخ أن يحيد عن هذا الأمر، هذا حرام منكر، من سنة الجاهلية، كان أهل الجاهلية لا يورثون النساء، والصبيان، ويورثون الذكور الكبار، وهذا غلط كبير، لا .... للمسلم أن يتشبه بالكفار، بل التركة للصغار، والكبار، والذكور، والإناث على قسمة الله، وليس للأب أن يلزم البنات، أو يعطيهم شيئًا من غير رضاهم ليسمحوا، لا، بل يجب أن يمكنوا من إرثهم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16275/حكم-حرمان-البنات-من-الارث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77111.mp3","categories":["الفرائض","الهبة والعطية","نصائح وتوجيهات"]},{"id":17920,"question":"تقول: في بعض مسائل الميراث، عندما يكون هناك إخوة لأم، وإخوة أشقاء، يكون نصيب الإخوة الأشقاء هو الباقي عصبة، لكن أحيانًا في بعض المسائل لا يبقى للأشقاء شيء، مع أنه يكون للإخوة الأم نصيب، فماذا نفعل في مثل هذه الحالة؟ هل نترك الأشقاء بلا ميراث؟","title":"مسألة إسقاط الإخوة الأشقاء من الميراث","answer":"الجواب: نعم، الصواب أنهم يسقطون، لاستغراق الفروض في المسألة؛ سقطوا على الصحيح من أقوال العلماء، لقول النبي ﷺ: ألحقوا الفرائض بأهلها، فما أبقت الفرائض فلأولى رجل ذكر رواه الشيخان: البخاري ومسلم في الصحيحين، فقوله: فما أبقت يدل على أنه إذا لم يبق شيء؛ يسقط.\nوقال قوم من أهل العلم: أنهم يشتركون مع الإخوة لأم، ويكون أبوهم كالعدم، كما وقع ذلك في عهد عمر ، فقالوا لإخوتهم: شركونا، وقدروا أن أبانا عدم، كأنه حجرٌ في اليم، كأنه حجر في البحر، ولكن هذا القول ضعيف، كما ينفعهم أبوهم، يضرهم أبوهم، ينفعهم إذا انفردوا، ويأخذون المال، ويأخذون ما بقي، فهكذا يضرهم إذا استغرقت الفروض، يضرهم، والحمد لله، هذا شرع الله الذي فيه الخير العظيم، وفيه العاقبة الحميدة. فإذا هلك هالك عن زوجٍ، وأمٍ، وأخوين لأم، وإخوة أشقاء، فإن المسألة تكون من ستة، للزوج النصف، ثلاثة، وللأم السدس، واحد[1]، وللأخوين من الأم الثلث، اثنان، تمت الست، ما بقي شيء، فيسقط الأشقاء، لأنها استغرقت الفروض المسألة، فهم داخلون في قوله ﷺ: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجلٍ ذكر هكذا إذا كانوا إخوةً لأب سقطوا.\nالمقصود؛ أن هذا هو الصحيح، وهذا يقال لها: المشركة، ويقال لها أيضًا: اليمية، والحجرية، ونحو ذلك، لكنها في الصحيح الأشقاء يسقطون، لاستغراق الفروض المسألة. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم. \n\n\n\n\tالصواب \"وللأم السدس، واحد\" وهو الظاهر من كلام الشيخ لأن سدس الستة واحد، ولعل قوله: اثنان، من قبيل سبق اللسان وإلا فالسياق يدل على مراده، وهذا الموضع نفسه قد تم تداركه في النسخة المطبوعة، ينظر: فتاوى نور على الدرب، طبعة الرئاسة العامة للبحوث العلمية والإفتاء (19/ 456-457).","link":"https://binbaz.org.sa/fatwas/16929/مسالة-اسقاط-الاخوة-الاشقاء-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72819.mp3","categories":["الفرائض"]},{"id":18039,"question":"يسأل أخونا ويقول: هل يجوز أن يرث المسلم الإنسان الذي يطوف حول القبور ويستغيث بها، وهل يجوز أن يرث المسلم تارك الصلاة؟","title":"حكم إرث الطائف حول القبور والتارك للصلاة","answer":"الجواب: يقول النبي ﷺ في الحديث الصحيح المتفق عليه: لا يرث المسلم الكافر، ولا الكافر المسلم، فالذي يطوف بالقبور ويستغيث بأهلها ويطلبهم المدد؛ لا يرث من المسلم، ولا يرثه المسلم؛ لهذا الحديث الصحيح : لا يرث المسلم الكافر، ولا الكافر المسلم. وإنما يرث هذا الذي يطوف بالقبور أمثاله من عباد القبور؛ لأنهم كفار مثله، ويرث المسلم أمثاله من المسلمين، فالمسلم يرث المسلم ولا يرث الكافر، وهكذا العكس، الكافر يرث الكافر ولا يرث المسلم؛ لقوله ﷺ: لا يرث المسلم الكافر ، ولا الكافر المسلم متفق على صحته، من حديث أسامة . نعم. المقدم: وبالنسبة لتارك الصلاة؟ الشيخ: كذلك تارك الصلاة؛ لأن الصحيح أنه كافر كفر أكبر، وقد ذهب بعض أهل العلم إلى أنه كفر أصغر، وأنه لا يكفر بذلك إذا كان يقر بالوجوب ولا يجحد الوجوب، ولكن الصواب أنه كافر كفرًا أكبر، وأن ورثته المسلمين لا يرثونه، يعني: أقاربه المسلمين لا يرثونه، وإنما يكون لبيت المال، يكون لبيت المال إرثه المال؛ لأنه مرتد بهذا. إلا إذا كان له أقارب مثله، إذا كان له أقارب مثله في ترك الصلاة فهم يرثونه كما يرث الكفار بعضهم بعضًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17071/حكم-ارث-الطاىف-حول-القبور-والتارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_600/60004.mp3","categories":["الفرائض"]},{"id":18189,"question":"هل يحق للأب أن يحرم ابنه من الإرث؟ وإذا كان ذلك غير جائز، فما هو توجيهكم لبعض الآباء؟ جزاكم الله خيرًا.","title":"حكم حرمان الوالد أحد ورثته من الميراث","answer":"الجواب: ليس له أن يحرم أحدًا من الورثة من حقه، وليس له أن يوصي لأحد بزيادة؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم، فليس للأب أن يجور في العطية، ولما أعطى بعض الصحابة بعض أولاده غلامًا، قال له ﷺ: أعطيت ولدك كلهم مثل هذا؟ قال: لا، قال: إني لا أشهد على جور سماه: جورًا. فالمقصود؛ أن الواجب على الإنسان أن يعدل في العطية بين أولاده، للذكر مثل حظ الأنثيين، كالإرث، إلا إذا كانوا مرشدين وسمحوا أن يعطى واحدًا منهم، أو بعضهم شيئًا زائد فلا بأس، الحق لهم، إذا كانوا مرشدين، ليسوا صغارًا، مرشدين وسمحوا أن يعطى واحد زيادة عليهم، لأسباب رأوها؛ فلا بأس، وليس له أن يوصي أيضًا لأحدهم بالزيادة على إرثه؛ لقوله عليه الصلاة والسلام: لا وصية لوارث، إن الله قد أعطى كل ذي حقٍ حقه، فلا وصية لوارث، فليس له أن يوصي لبعض الأولاد بشيء زائد، أو لغيرهم من الورثة، لا الواجب تركهم على ما قسم الله، إن الله قد أعطى كل ذي حقٍ حقه، فلا وصية لوارث نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17226/حكم-حرمان-الوالد-احد-ورثته-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73113.mp3","categories":["الفرائض","الهبة والعطية"]},{"id":18391,"question":"أخونا يسأل عن قضية في الميراث، فيقول: ما حق امرأة كانت متزوجة برجل، مكثت معه مدة تسعة عشر عامًا، فمات ولم تنجب أولادًا منه، فبقي أخوه يعمل وكون أملاكًا أخرى لمدة أربعة عشر عامًا ومات، ولم تأخذ نصيبها منه، هل عندها الحق في الأملاك كلها أم لا، علمًا بأن الأخ أيضًا لم ينجب أولادًا، أفيدونا جزاكم الله خيرًا؟","title":"ما حق المرأة التي مات زوجها ولم تنجب أولادًا؟","answer":"الجواب: هذه مسألة تتعلق بالمحاكم، فالمحكمة تنظر في الأمر وتعطي المرأة حقها من زوجها، فلها حقها من زوجها وهو الربع إذا لم يكن له ذرية من غيرها لها الربع، كما قال الله تعالى: وَلَهُنَّ الرُّبُعُ مِمَّا تَرَكْتُمْ إِنْ لَمْ يَكُنْ لَكُمْ وَلَدٌ [النساء:12]، فإذا كان زوجها ليس له ذرية من غيرها، وهي لم تنجب منه شيئًا؛ فإن لها الربع من أملاكه. وأما التفصيل في أملاكه وأملاك أخيه والنظر في ذلك، فهذا يرجع إلى المحكمة لإثبات ما يخصه دون أخيه، فلها الحق فيما خلفه زوجها، أما أموال أخي زوجها فليس لها الحق في ذلك. نعم. المقدم: إذا خلط المالين جميعًا سماحة الشيخ؟ الشيخ: تنظر المحكمة حتى يميز مال زوجها من مال أخيه، فلها الإرث في مال زوجها، دون مال أخيه. نعم. المقدم: في مال زوجها وأرباحه -مثلاً-؟ الشيخ: هذا إلى المحكمة تنظر في هذا. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17468/ما-حق-المراة-التي مات-زوجها-ولم-تنجب-اولادا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86302.mp3","categories":["الفرائض"]},{"id":18870,"question":"سؤاله الثاني يتعلق بالتركات وقسمتها، فيسأل ويقول: توفيت امرأة وتركت أولادًا أربعة ذكور وثلاث إناث وزوجًا، وله زوجة أخرى، وله منها أولاد ذكور اثنين وأنثى واحدة، وتركت المتوفاة ثروة قدرها ثلاثة عشر ألف جنيه مصري، فكيف تقسم هذه التركة بين زوجها وأولادها، وضرتها وأولادها؟علمًا بأن الزوج قد توفي أيضًا بعدها بعام.","title":"قسمة تركة امرأة توفيت عن: زوج وأولاد ثم توفي زوجها","answer":"الجواب: تركة الزوجة تقسم بين زوجها وأولادها فقط، زوجها له الربع من هذا المال، والباقي لأولادها الأربعة، وبناتها الثلاث، يجعل الباقي أحد عشر سهمًا، ثمانية للأولاد الأربعة الذكور، وثلاثة للبنات الثلاث للذكر مثل حظ الأنثيين، فيعطى الزوج الربع، والباقي لأولادها الأربعة، والبنات الثلاث على أحد عشر سهمًا، ثمانية للبنين لكل واحد سهمان، وثلاثة سهام للبنات لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]. ثم حق الزوج، وهو الربع، يقسم بين أولاده جميعًا، حق الزوج يقسم بين أولاده من الزوجتين، وتعطى زوجته الأخيرة التي مات عنها، تعطى: ثمنها، ثمن هذا الذي حصل له من زوجته الأولى، تعطى الزوجة الثمن مع ثمن ما وراه من المال غير حقه من الزوجة، ويقسم الباقي بين الذرية كلهم بين أولاده كلهم من هذه وهذه، نعم. المقدم: جزاكم الله خيرًا، إذًا: الضرة وأولادها ليس لهم شيء في التركة. الشيخ: ليس لهم حق في مال الزوجة الأولى، وإنما حقهم في ربع الزوج الذي أخذه من زوجته، هذا الربع للجميع، تعطى الزوجة نصيبها وهو الثمن، والباقي بين أولادها وأولاد الأولى، هذا الربع، مع بقية التركة التي للزوج إذا كان عنده مال غير هذا الربع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18005/قسمة-تركة-امراة-توفيت-عن-زوج-واولاد-ثم-توفي-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92209.mp3","categories":["الفرائض"]},{"id":18941,"question":"تقول هذه السائلة: إذا توفيت المرأة قبل وفاة أبيها، ولها أطفال صغار قصر، فهل يجوز لهؤلاء الأطفال أن يرثوا نصيب أمهم عند وفاة أبيها؟ علمًا بأن زوج هذه المرأة متوفى.","title":"حكم توريث أولاد البنت","answer":"الجواب: أولاد البنت لا يرثون من جدهم أبي أمهم، الورث لغيرهم من أولاد الميت أو أولاد بنيه، أما أولاد البنات فليسوا من الورثة، وإنما هم من ذوي الأرحام على الاختلاف في إرثهم، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18061/حكم-توريث-اولاد-البنت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88202.mp3","categories":["الفرائض"]},{"id":19038,"question":"أخونا له قضية أخرى يقول فيها: توفي جدي لوالدي قبل ستة عشر سنة، وترك أرضًا زراعية وخلف أولادًا وبنات، ولكن عندنا بعض الناس لا يجعلون للبنات نصيبًا من تركة الأب، قام الأولاد بزراعة الأرض، وبعد ذلك بخمس سنوات رحلنا عن البلاد إلى خارجها وبقي اثنان من العيال، وقام الأولاد بزراعة الأرض، واستغلوها لمدة خمس سنوات.هذا الأمر تم وأنا صغير، وبعد أن كبرت وقرأت القرآن وعرفت تقسيم التركة بين الأبناء والبنات، أريد أن أعرف رأي الشرع في هذا، خاصة بعد الفترة التي مرت دون حصول إحدى البنات على شيء.وبالمناسبة البنات كلهن متزوجات، وهن في غنى عن هذا، هل إذا تنازلن البنات عن نصيبهن في هذا من سابق إلى الآن تبرأ الذمة؟ نرجو التوجيه جزاكم الله خيرًا.","title":"حكم حرمان البنات من الميراث","answer":"الجواب: عدم إعطاء البنات حصتهن من الإرث، هذا أمر جاهلي من أمر الجاهلية، كان أهل الجاهلية لا يورثون البنات ولا الصغار، ويقولون: إنما يأخذ المال من يحمل السلاح ويقاتل الرجال، وهذا غلط كبير، وقد أنزل الله القرآن العظيم، وبعث رسوله الكريم عليه الصلاة والسلام بشرائع محكمة، وجعل من ذلك أن المال بين الذكور والإناث، لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] من الأولاد والإخوة للأبوين أو للأب، وجعل للإخوة من الأم فرضًا خاصًا. فالواجب على المسلمين أن يسيروا على نهج الشريعة، وأن يلتزموا بما حكم الله به فيعطوا البنات حقهن والذكور حقهم، وعليهم أن يؤدوا للبنات ما سبق أن أخذوه من حقهن إلا إذا سمحن وتنازلن عن حقهن السابق أو اللاحق، وهن مرشدات بالغات لا بأس بذلك، وعليك أن تراجع المحكمة في كل ما أشكل عليك، مما يتعلق بالماضي والحاضر حتى تسير على أمر بين في جميع أمور التركة، لا في الحاضر ولا في المستقبل ولا في الماضي، ومن سمح من البنات المزوجات أو غير المزوجات وهن مرشدات مكلفات عن بعض حقهن أو عن حقهن فلا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18205/حكم-حرمان-البنات-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92802.mp3","categories":["الفرائض"]},{"id":19105,"question":"أحد الإخوة المستمعين بعث رسالة وضمنها قضية يقول فيها: مات ميت، وترك زوجتين، وثمانية أولاد، فقامت إحداهن وهي أم البنات بإحضار مال مقداره مائة ألف ريال، ثم بعد ذلك وزعته على بناتها، وعندما عرف البنات أن هذا المال لا يصح، وأنه حرام؛ قمن فتصدقن بالمال، فما حكم ذلك؟ علمًا بأن أم الأولاد كان لديها مبلغ مقابل، ولم يصرحوا بهذا، فما رأي سماحتكم؟ جزاكم الله خيرًا.","title":"حكم تقسيم شيء من التركة على بعض الورثة دون الآخرين","answer":"الجواب: هذا فيه تفصيل: إن كان هذا المال جلبته من جهة أخرى من خيانة، أو سرقة، أو أشباه ذلك، فهذا المال حرام، والصدقة به في الفقراء والمساكين من البنات أمر طيب، ليس لهن أن يأكلن الحرام، وهم يعرفون أو يعلمون أنه حرام. لكن إذا علموا أن صاحب المال فلان وجب رده إليه، كان مسروقًا منه، أو مغصوبًا منه؛ يجب رده إلى صاحبه، فإن كان المال من كسبها الحرام من الربا، أو من أكساب أخرى؛ ليس له مالك معروف، ولا يعرفون أحدًا يملكه، ولا يدرون من أين جاء هذا المال، إلا أنهم يعرفون أنه حرام؛ فإذا تصدقوا به فلا شيء عليهم. أما إن كان المال من مال الميت، فليس لها حق أن تعطي بناتها إلا حقهم، لا تعطيهم إلا الحق، لأن معها زوجة ثانية فالزوجة الثانية لها نصف الثمن، والبنات لهن الثلثان، فيبقى بقية للعاصب، فإذا كان المال من مال الزوج الميت فلا حق لها أن تعطي بناتها إلا نصيبهن فقط لا زيادة. وفي إمكان البنات أن يتحاسبن مع أمهن، ويعطين الزوجة نصيبها، والعاصب نصيبه من المال الذي خلفه الزوج، وليس لهن أن يتصدقن به على أحد، بل هذا مال مشترك. والنظر في موضوعه: هل هو حرام أو ما هو بحرام؟ هذا مشترك بين الورثة، وإذا اشتبه عليهم يرجعون للحاكم في المحكمة، وتبين لهم المحكمة الحكم الشرعي، ولا يتصرفوا في مال غيرهم. المقصود أنه إذا كان للميت هذا المال للميت فليس لأم البنات التصرف فيه وحدها، بل ليس لها إلا حقها، وليس للبنات إلا حقهن، وللزوجة حقها الثانية، وللعصبة حقهم، والنظر في كونه حرامًا أو ليس بحرام هذا يرجع إليهم جميعًا، إذا اتفقوا على شيء، وتصدقوا به جميعًا، أو تصدق بعضهم بنصيبه هذا إليهم، وإن أشكل عليهم يراجعون المحكمة، والمحكمة ترشدهم، أو إلى بعض العلماء في بلدهم، بعض علماء الحق حتى يبين لهم الحكم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18289/حكم-تقسيم-شيء-من-التركة-على-بعض-الورثة-دون-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79708.mp3","categories":["الفرائض"]},{"id":19119,"question":"يقول في قضية أخرى: إذا قتل رجل أخاه، وعفا الأب عن هذا القاتل، فهل يرث القاتل من المقتول؟","title":"حكم إرث القاتل من المقتول","answer":"الجواب: لا يرث القاتل من المقتول إذا كان قتله عمدًا عدوانًا؛ فإنه لا يرث منه، وهكذا لو كان خطأً أوجب عليه الدية أو الكفارة فإنه لا يرث منه للحديث: ليس للقاتل من الميراث شيء. وقد أجمع العلماء رحمهم الله على أن القاتل لا يرث من المقتول، إذا كان قتلًا مضمونًا ولو عفا الأب، لكن إذا سمح الورثة الباقون أن يشركوه فلا حرج عليهم، إذا كانوا مكلفين مرشدين، وسمحوا بأن يرث معهم هذا القاتل فلا بأس، أو كان الوارث الأب أبا المقتول وأبا القاتل وسمح أن يرث من المقتول لكن سمح والده أن يرث من المقتول فالحق له، إذا كان القاتل له إرث بأن قتل مثلًا أخاه والوالد لا يرث لكونه رقيقًا أو كافرًا والقتيل مسلم. أما إذا كان القتيل مسلمًا والأب مسلمًا، أو القتيل كافرًا والأب كافرًا؛ فإن الإرث للأب يحجب الإخوة. الحاصل: أنه إذا كان القاتل يرث لولا القتل وسمح الورثة له بالمشاركة وهم مكلفون مرشدون فلا بأس بذلك، الحق لهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18297/حكم-ارث-القاتل-من-المقتول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_931/nour_93107.mp3","categories":["الفرائض"]},{"id":19392,"question":"مستمع من السودان يسأل ويقول: هل دية المقتول تقسم بين ورثته؟","title":"دية المقتول تقسم بين ورثته","answer":"الجواب: نعم الدية مثل التركة، جزء من التركة، تقسم بين الورثة جميعهم، إلا إذا كان أحدهم قاتلًا فليس له شيء، القاتل ليس له إرث، لكن الورثة الذين ليس فيهم القاتل تقسم بينهم التركة، والدية للجميع، الدية من جملة التركة.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18613/دية-المقتول-تقسم-بين-ورثته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74007.mp3","categories":["الفرائض"]},{"id":19444,"question":"له سؤال طويل سماحة الشيخ يذكر فيه أن والده كان لا يحافظ على الصلاة، وقد توفي وهو على ذلكم الحال، وخلف تركة، كيف يكون موقفهم من هذه التركة، وكيف يقتسمها هو وإخوته؟","title":"حكم أخذ الورثة من تركة تارك الصلاة","answer":"الجواب: عليك أن تراجع المحكمة أنت وإخوتك. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18684/حكم-اخذ-الورثة-من-تركة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74015.mp3","categories":["الفرائض"]},{"id":19608,"question":"هذا سائل للبرنامج يقول: سماحة الشيخ هناك أناس يمنعون النساء من الميراث، فهل من توجيه لهم ونصيحة مأجورين؟","title":"توجيه للذين يمنعون النساء من الميراث","answer":"الجواب: هذا من دين الجاهلية، هذا من دين الجاهلية، ومن أخلاق الكفرة، كان الكفار لا يورثون النساء، وهذا باطل، الواجب توريثهم ما أعطاهم الله، ولا يجوز لأحد الاعتراض على ذلك، وهذا نوع من الجاهلية، ومن استحل هذا كفر، نسأل الله العافية. لا بد أن يعطوا ما فرض الله لهم، وما شرع الله لهم، والذي يعارض في هذا من سنة الجاهلية وأخلاق الجاهلية، وإذا جحد ما شرعه الله كفر، نسأل الله العافية. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18881/توجيه-للذين-يمنعون-النساء-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94814.mp3","categories":["الفرائض"]},{"id":19658,"question":"تقول السائلة يا سماحة الشيخ: توفي والدي وترك بعضًا من أغراض المنزل، ولم يقسمها الورثة، فما حكم ذلك، علمًا بأن العائلة لا يرضون بقسمة الأغراض والوالدة لا ترغب في ذلك؟","title":"حكم عدم قسمة بعض ما تركه الميت","answer":"الجواب: كل ما خلف الميت فهو تركة بين الجميع، فإذا رغبوا عن بعض الشيء يتصدق به، إذا سمحوا كقميص أو سراويل أو فراش أو عباءة أو شيء، إذا سمح الورثة وهم مرشدون أن يتصدق به فلا بأس وإلا فهو بينهم يبيعونه أو يقتسمونه، سواء كان فرش أو ملابس أو غير ذلك، إلا ما سمحوا به وهم مكلفون مرشدون ويعطاه الفقراء فلا بأس، أما الصغار فلابد من ضبط حقهم، يثمن ويعرف حق الصغار ثم يتصدق به على الفقراء لا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18942/حكم-عدم-قسمة-بعض-ما-تركه-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95012.mp3","categories":["الفرائض"]},{"id":19695,"question":"توفى رجل، وترك: زوجة وبنتين وأخ من الأم فقط، فهل يرث أخوه هذا أم لا؟ وإذا كان يرث فعلًا، فما هو نصيب كل واحد من الورثة، علمًا بأن التركة التي خلفها هي من ماله الخاص؟","title":"مات عن: زوجة وبنتين وأخ من أم","answer":"الجواب:\n\nهذا الميت تقسم تركته من أربعة وعشرين: للبنتين: الثلثان (16)، وللزوجة: الثمن (3)، ويبقى خمسة، يعطاها العاصب إذا كان له عاصب، ولو بعيد فإن لم يكن له عاصب، فإنها ترد عند أهل العلم للبنتين.\n\nأما الأخ فلا يرث مع وجود الفرع؛ لأن الله جل وعلا قال في كتابه العظيم: وَإِن كَانَ رَجُلٌ يُورَثُ كَلاَلَةً أَو امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِّنْهُمَا السُّدُسُ فَإِن كَانُوَاْ أَكْثَرَ مِن ذَلِكَ فَهُمْ شُرَكَاء فِي الثُّلُثِ [النساء:12]، والكلالة: من لا والد له ولا ولد، وهاتان البنتان وجودهما يجعل المسألة ليست كلالة، فيسقط بذلك الأخ من الأم لفقد شرطه؛ لأن شرط الإرث الأخ للأم أن تكون المسألة كلالة، كما في هذه الآية الكريمة، وهي قوله  في سورة (النساء): وَإِن كَانَ رَجُلٌ يُورَثُ كَلاَلَةً أَو امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ يعني من أم فَلِكُلِّ وَاحِدٍ مِّنْهُمَا السُّدُسُ فَإِن كَانُوَاْ أَكْثَرَ مِن ذَلِكَ فَهُمْ شُرَكَاء فِي الثُّلُثِ، وهذا ميت له بنات فلم تكن المسألة كلالة، فيكون الأخ من الأم لا حق له في الإرث.\n\nوالباقي بعد الزوجة والبنتين يكون لأقرب العصبة، فإن لم يكن له عصبه، فإنه يعطى الباقي للبنتين، ويكون إرثهما فرضًا وردًا: (16) فرضًا، (5) ردًا. هذا هو الصواب الذي نفتي به، وهو قول أهل العلم[1].\n\n\n\n\tمن برنامج (نور على الدرب). (مجموع فتاوى ومقالات الشيخ ابن باز 20/ 241).","link":"https://binbaz.org.sa/fatwas/19294/مات-عن-زوجة-وبنتين-واخ-من-ام","audio":"","categories":["الفرائض"]}]
